async function updateClipAnnotations(id, annotations) {
  const db = await openClipsDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(CLIPS_STORE, "readwrite");
    const store = tx.objectStore(CLIPS_STORE);
    const getReq = store.get(id);
    getReq.onsuccess = () => {
      const clip = getReq.result;
      if (!clip) { resolve(false); return; }
      clip.annotations = annotations;
      store.put(clip);
    };
    tx.oncomplete = () => resolve(true);
    tx.onerror = () => reject(tx.error);
  });
}

