const VOLUNTEER_TASK_SUGGESTIONS = ["Buvette", "Goûter/collation", "Marquage du terrain", "Table de marque", "Arbitrage de touche", "Accueil des visiteurs", "Rangement du matériel"];

function ClubVolunteerSlotsScreen() {
  const [slots, setSlots] = useState([]);
  const [events, setEvents] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState(emptyVolunteerSlot());
  const [signingId, setSigningId] = useState(null);
  const [volunteerName, setVolunteerName] = useState("");

  useEffect(() => {
    try { setSlots(JSON.parse(localStorage.getItem("tf_club_volunteer_slots") || "[]")); } catch (e) {}
    try {
      const comp = loadCompetitionsData();
      const sessions = JSON.parse(localStorage.getItem("tf_sessions") || "[]");
      const clubEvents = JSON.parse(localStorage.getItem("tf_club_events") || "[]");
      setEvents(buildAccueilEvents(comp, sessions, clubEvents).filter((e) => e.date >= todayIso()).sort((a, b) => new Date(a.date) - new Date(b.date)));
    } catch (e) { setEvents([]); }
    setLoaded(true);
  }, []);

  function persist(next) {
    setSlots(next);
    try { localStorage.setItem("tf_club_volunteer_slots", JSON.stringify(next)); } catch (e) { alert("La sauvegarde a échoué."); }
  }
  function save() {
    if (!form.task.trim()) { alert("Décris la tâche à assurer."); return; }
    if (!form.eventTitle) { alert("Choisis un événement."); return; }
    persist([...slots, form]);
    setShowForm(false);
    setForm(emptyVolunteerSlot());
  }
  function remove(id) {
    if (!confirm("Supprimer ce créneau bénévole ?")) return;
    persist(slots.filter((s) => s.id !== id));
  }
  function signUp(slotId) {
    if (!volunteerName.trim()) { alert("Indique ton nom."); return; }
    persist(slots.map((s) => (s.id === slotId ? { ...s, volunteers: [...s.volunteers, volunteerName.trim()] } : s)));
    setSigningId(null);
    setVolunteerName("");
  }
  function withdraw(slotId, name) {
    persist(slots.map((s) => (s.id === slotId ? { ...s, volunteers: s.volunteers.filter((v) => v !== name) } : s)));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const upcoming = slots.filter((s) => s.eventDate >= todayIso()).sort((a, b) => new Date(a.eventDate) - new Date(b.eventDate));

  return (
    <div>
      <p className="radar-note">Créneaux bénévoles pour les événements du club — buvette, goûter, table de marque... chacun peut s'inscrire sur ce dont le club a besoin.</p>

      {!showForm && <button className="btn btn-primary btn-large" onClick={() => setShowForm(true)} style={{ marginBottom: 16 }}>+ Nouveau créneau</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Événement
            <select value={form.eventTitle} onChange={(e) => { const ev = events.find((x) => x.title === e.target.value); setForm((f) => ({ ...f, eventTitle: e.target.value, eventDate: ev?.date || "" })); }}>
              <option value="">Choisir…</option>
              {events.map((ev, i) => <option key={i} value={ev.title}>{formatDateFr(ev.date)} — {ev.title}</option>)}
            </select>
          </label>
          <label>Tâche<input type="text" list="volunteer-task-datalist" placeholder="ex. Buvette" value={form.task} onChange={(e) => setForm((f) => ({ ...f, task: e.target.value }))} /></label>
          <datalist id="volunteer-task-datalist">
            {VOLUNTEER_TASK_SUGGESTIONS.map((t) => <option key={t} value={t} />)}
          </datalist>
          <label>Nombre de bénévoles nécessaires<input type="number" min="1" value={form.neededCount} onChange={(e) => setForm((f) => ({ ...f, neededCount: Number(e.target.value) }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => setShowForm(false)}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Créer</button>
          </div>
        </div>
      )}

      {upcoming.length === 0 && <div className="empty-state">Aucun créneau bénévole pour l'instant.</div>}
      <div className="scouting-list">
        {upcoming.map((s) => {
          const full = s.volunteers.length >= s.neededCount;
          return (
            <div className="scouting-card" key={s.id} style={{ flexDirection: "column", alignItems: "stretch" }}>
              <div className="scouting-info">
                <div className="scouting-name">{s.task} <span className="scouting-club">{s.eventTitle}</span></div>
                <div className="scouting-meta">{formatDateFr(s.eventDate)} · {s.volunteers.length}/{s.neededCount} bénévole{s.neededCount !== 1 ? "s" : ""}{full ? " · complet" : ""}</div>
                {s.volunteers.length > 0 && (
                  <div className="scouting-meta">
                    {s.volunteers.map((v) => (
                      <span key={v} style={{ marginRight: 8 }}>{v} <button className="icon-btn" style={{ padding: 0 }} onClick={() => withdraw(s.id, v)} aria-label={`Retirer ${v}`}>✕</button></span>
                    ))}
                  </div>
                )}
              </div>
              <div style={{ display: "flex", gap: 6, marginTop: 6 }}>
                {!full && (signingId === s.id ? (
                  <>
                    <input type="text" placeholder="Ton nom" value={volunteerName} onChange={(e) => setVolunteerName(e.target.value)} style={{ maxWidth: 160 }} />
                    <button className="btn btn-ghost btn-small" onClick={() => signUp(s.id)}>Confirmer</button>
                  </>
                ) : (
                  <button className="btn btn-ghost btn-small" onClick={() => setSigningId(s.id)}>Je m'inscris</button>
                ))}
                <button className="icon-btn" onClick={() => remove(s.id)} aria-label="Supprimer">✕</button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ClubCarpoolScreen() {
  const [offers, setOffers] = useState([]);
  const [events, setEvents] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState(emptyCarpoolOffer());
  const [joiningId, setJoiningId] = useState(null);
  const [passengerName, setPassengerName] = useState("");

  useEffect(() => {
    try { setOffers(JSON.parse(localStorage.getItem("tf_club_carpool") || "[]")); } catch (e) {}
    try {
      const comp = loadCompetitionsData();
      const sessions = JSON.parse(localStorage.getItem("tf_sessions") || "[]");
      const clubEvents = JSON.parse(localStorage.getItem("tf_club_events") || "[]");
      setEvents(buildAccueilEvents(comp, sessions, clubEvents).filter((e) => e.date >= todayIso()).sort((a, b) => new Date(a.date) - new Date(b.date)));
    } catch (e) { setEvents([]); }
    setLoaded(true);
  }, []);

  function persist(next) {
    setOffers(next);
    try { localStorage.setItem("tf_club_carpool", JSON.stringify(next)); } catch (e) { alert("La sauvegarde a échoué."); }
  }
  function save() {
    if (!form.driverName.trim()) { alert("Indique qui conduit."); return; }
    if (!form.eventTitle) { alert("Choisis un événement."); return; }
    persist([...offers, form]);
    setShowForm(false);
    setForm(emptyCarpoolOffer());
  }
  function remove(id) {
    if (!confirm("Supprimer cette offre de covoiturage ?")) return;
    persist(offers.filter((o) => o.id !== id));
  }
  function join(offerId) {
    if (!passengerName.trim()) { alert("Indique ton nom."); return; }
    persist(offers.map((o) => (o.id === offerId ? { ...o, passengers: [...o.passengers, passengerName.trim()] } : o)));
    setJoiningId(null);
    setPassengerName("");
  }
  function leave(offerId, name) {
    persist(offers.map((o) => (o.id === offerId ? { ...o, passengers: o.passengers.filter((p) => p !== name) } : o)));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const upcoming = offers.filter((o) => o.eventDate >= todayIso()).sort((a, b) => new Date(a.eventDate) - new Date(b.eventDate));

  return (
    <div>
      <p className="radar-note">Covoiturage pour les déplacements — chaque conducteur propose ses places, les autres s'y ajoutent comme passagers.</p>

      {!showForm && <button className="btn btn-primary btn-large" onClick={() => setShowForm(true)} style={{ marginBottom: 16 }}>+ Proposer un trajet</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Événement
            <select value={form.eventTitle} onChange={(e) => { const ev = events.find((x) => x.title === e.target.value); setForm((f) => ({ ...f, eventTitle: e.target.value, eventDate: ev?.date || "" })); }}>
              <option value="">Choisir…</option>
              {events.map((ev, i) => <option key={i} value={ev.title}>{formatDateFr(ev.date)} — {ev.title}</option>)}
            </select>
          </label>
          <label>Conducteur<input type="text" value={form.driverName} onChange={(e) => setForm((f) => ({ ...f, driverName: e.target.value }))} autoFocus /></label>
          <div className="roster-physical-grid">
            <label>Places disponibles<input type="number" min="1" value={form.seats} onChange={(e) => setForm((f) => ({ ...f, seats: Number(e.target.value) }))} /></label>
            <label>Heure de départ<input type="time" value={form.departureTime} onChange={(e) => setForm((f) => ({ ...f, departureTime: e.target.value }))} /></label>
          </div>
          <label>Lieu de départ<input type="text" value={form.departureLocation} onChange={(e) => setForm((f) => ({ ...f, departureLocation: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => setShowForm(false)}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Proposer</button>
          </div>
        </div>
      )}

      {upcoming.length === 0 && <div className="empty-state">Aucun trajet proposé pour l'instant.</div>}
      <div className="scouting-list">
        {upcoming.map((o) => {
          const full = o.passengers.length >= o.seats;
          return (
            <div className="scouting-card" key={o.id} style={{ flexDirection: "column", alignItems: "stretch" }}>
              <div className="scouting-info">
                <div className="scouting-name">{o.eventTitle} <span className="scouting-club">{formatDateFr(o.eventDate)}</span></div>
                <div className="scouting-meta">{o.driverName} conduit{o.departureLocation ? ` depuis ${o.departureLocation}` : ""}{o.departureTime ? ` à ${o.departureTime}` : ""} · {o.passengers.length}/{o.seats} place{o.seats !== 1 ? "s" : ""}{full ? " · complet" : ""}</div>
                {o.passengers.length > 0 && (
                  <div className="scouting-meta">
                    {o.passengers.map((p) => (
                      <span key={p} style={{ marginRight: 8 }}>{p} <button className="icon-btn" style={{ padding: 0 }} onClick={() => leave(o.id, p)} aria-label={`Retirer ${p}`}>✕</button></span>
                    ))}
                  </div>
                )}
              </div>
              <div style={{ display: "flex", gap: 6, marginTop: 6 }}>
                {!full && (joiningId === o.id ? (
                  <>
                    <input type="text" placeholder="Ton nom" value={passengerName} onChange={(e) => setPassengerName(e.target.value)} style={{ maxWidth: 160 }} />
                    <button className="btn btn-ghost btn-small" onClick={() => join(o.id)}>Confirmer</button>
                  </>
                ) : (
                  <button className="btn btn-ghost btn-small" onClick={() => setJoiningId(o.id)}>Rejoindre</button>
                ))}
                <button className="icon-btn" onClick={() => remove(o.id)} aria-label="Supprimer">✕</button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function emptyGateReceipt() {
  return { id: newId(), matchLabel: "", date: todayIso(), ticketsSold: 0, ticketPrice: 0, otherRevenue: 0, notes: "" };
}

function ClubGateReceiptsScreen() {
  const [receipts, setReceipts] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyGateReceipt());

  useEffect(() => {
    try { setReceipts(JSON.parse(localStorage.getItem("tf_club_gate_receipts") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setReceipts(next);
    try { localStorage.setItem("tf_club_gate_receipts", JSON.stringify(next)); } catch (e) { alert("La sauvegarde a échoué."); }
  }
  function openNew() { setForm(emptyGateReceipt()); setEditingId(null); setShowForm(true); }
  function openEdit(r) { setForm({ ...emptyGateReceipt(), ...r }); setEditingId(r.id); setShowForm(true); }
  function save() {
    if (!form.matchLabel.trim()) { alert("Indique le match concerné."); return; }
    if (editingId) persist(receipts.map((r) => (r.id === editingId ? form : r)));
    else persist([...receipts, form]);
    setShowForm(false);
  }
  function remove(id) {
    if (!confirm("Supprimer cette recette de match ?")) return;
    persist(receipts.filter((r) => r.id !== id));
  }
  function matchTotal(r) { return Number(r.ticketsSold || 0) * Number(r.ticketPrice || 0) + Number(r.otherRevenue || 0); }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const seasonTotal = receipts.reduce((s, r) => s + matchTotal(r), 0);

  return (
    <div>
      <p className="radar-note">Recettes de billetterie par match à domicile — entrées vendues, buvette et autres recettes annexes. {receipts.length > 0 && `Total saison : ${seasonTotal}€.`}</p>

      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Ajouter une recette de match</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Match<input type="text" placeholder="ex. vs Racing Club" value={form.matchLabel} onChange={(e) => setForm((f) => ({ ...f, matchLabel: e.target.value }))} autoFocus /></label>
          <label>Date<input type="date" value={form.date} onChange={(e) => setForm((f) => ({ ...f, date: e.target.value }))} /></label>
          <div className="roster-physical-grid">
            <label>Entrées vendues<input type="number" min="0" value={form.ticketsSold} onChange={(e) => setForm((f) => ({ ...f, ticketsSold: Number(e.target.value) }))} /></label>
            <label>Prix du billet (€)<input type="number" min="0" step="0.01" value={form.ticketPrice} onChange={(e) => setForm((f) => ({ ...f, ticketPrice: Number(e.target.value) }))} /></label>
          </div>
          <label>Autres recettes (buvette, etc., €)<input type="number" min="0" step="0.01" value={form.otherRevenue} onChange={(e) => setForm((f) => ({ ...f, otherRevenue: Number(e.target.value) }))} /></label>
          <label>Notes<textarea rows={2} value={form.notes} onChange={(e) => setForm((f) => ({ ...f, notes: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => setShowForm(false)}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}

      {receipts.length === 0 && <div className="empty-state">Aucune recette de match enregistrée pour l'instant.</div>}
      <div className="scouting-list">
        {[...receipts].sort((a, b) => new Date(b.date) - new Date(a.date)).map((r) => (
          <div className="scouting-card" key={r.id} onClick={() => openEdit(r)} style={{ cursor: "pointer" }}>
            <div className="scouting-info">
              <div className="scouting-name">{r.matchLabel} <span className="scouting-club">{matchTotal(r)}€</span></div>
              <div className="scouting-meta">{formatDateFr(r.date)} · {r.ticketsSold} entrée{r.ticketsSold !== 1 ? "s" : ""} à {r.ticketPrice}€{r.otherRevenue > 0 ? ` · +${r.otherRevenue}€ autres recettes` : ""}</div>
            </div>
            <button className="icon-btn" onClick={(e) => { e.stopPropagation(); remove(r.id); }} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

const SPONSOR_CONTRIBUTION_TYPES = ["Financier", "Matériel/équipement", "Prestation de service", "Autre"];
function emptySponsor() {
  return { id: newId(), name: "", contactName: "", contactInfo: "", contribution: "", contributionType: "Financier", startDate: todayIso(), renewalDate: "", notes: "" };
}
// Réutilise le même seuil que les alertes diplômes/honorabilité (60 jours) pour rester cohérent.
function isSponsorRenewalSoon(dateStr, daysThreshold = 60) {
  if (!dateStr) return false;
  const diffDays = (new Date(dateStr) - new Date()) / (1000 * 60 * 60 * 24);
  return diffDays < daysThreshold;
}

// Portail joueur/parent — vue consolidée et volontairement limitée à ce qui concerne CE joueur :
// pas de projet de jeu, pas d'informations sur d'autres joueurs, pas de détail médical clinique
// (juste un statut simple). Fonctionne dès maintenant en impression/PDF (comme le reste de l'app) ;
// sa vraie valeur — un accès direct pour le joueur/parent sur son propre appareil — reste bloquée
// tant qu'il n'y a pas de serveur, puisque tout reste dans TON navigateur à toi.
function PortailJoueurScreen() {
  const [roster, setRoster] = useState([]);
  const [selectedId, setSelectedId] = useState("");
  const [devPlans, setDevPlans] = useState({});
  const [programs, setPrograms] = useState({});
  const [injuries, setInjuries] = useState([]);
  const [sessions, setSessions] = useState([]);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setRoster(JSON.parse(localStorage.getItem("tf_roster") || "[]")); } catch (e) {}
    try { setDevPlans(JSON.parse(localStorage.getItem("tf_development_plans") || "{}")); } catch (e) {}
    try { setPrograms(JSON.parse(localStorage.getItem("tf_individual_programs") || "{}")); } catch (e) {}
    try { setInjuries(JSON.parse(localStorage.getItem("tf_medical_injuries") || "[]")); } catch (e) {}
    try { setSessions(JSON.parse(localStorage.getItem("tf_sessions") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const player = roster.find((p) => p.id === selectedId);
  const objectives = selectedId ? (devPlans[selectedId] || []) : [];
  const playerPrograms = selectedId ? (programs[selectedId] || []) : [];
  const activeInjury = injuries.find((i) => i.playerId === selectedId && i.status === "en cours");
  const upcomingSessions = sessions.filter((s) => s.date >= todayIso()).sort((a, b) => new Date(a.date) - new Date(b.date)).slice(0, 5);

  return (
    <div className="stats-screen" style={{ maxWidth: 800, margin: "0 auto" }}>
      <div className="stats-screen-header">
        <div className="eyebrow">Vestiaire</div>
        <h1>Portail joueur/parent</h1>
        <p className="subtitle">Un résumé pensé pour être montré ou imprimé pour un joueur ou ses parents — pas le tableau de bord complet du coach. Pour l'instant, ça reste dans ton navigateur : utile comme support imprimé dès aujourd'hui, un vrai accès depuis leur propre appareil attendra un serveur.</p>
      </div>

      <label style={{ display: "inline-block", marginBottom: 16 }} className="no-print">
        Joueur
        <select value={selectedId} onChange={(e) => setSelectedId(e.target.value)} style={{ display: "block", marginTop: 4 }}>
          <option value="">Choisir…</option>
          {roster.map((p) => <option key={p.id} value={p.id}>{playerFullName(p)}</option>)}
        </select>
      </label>

      {!player && <div className="empty-state no-print">Choisis un joueur pour voir son résumé.</div>}

      {player && (
        <>
          <button className="btn btn-ghost btn-small no-print" onClick={() => window.print()} style={{ marginBottom: 16 }}><Download size={13} /> Imprimer / Exporter en PDF</button>

          <div className="panel-heading" style={{ marginTop: 0 }}>{playerFullName(player)}</div>
          <p className="hint" style={{ marginTop: 0 }}>{player.position}{player.birthDate ? ` · ${computeAge(player.birthDate)} ans` : ""}</p>

          {activeInjury && (
            <div className="empty-state" style={{ marginBottom: 16 }}>
              Actuellement en soin — {RTP_STAGES.find((s) => s.key === (activeInjury.rtpStage || "arret_complet"))?.label || "arrêt complet"}.
            </div>
          )}

          <div className="panel-heading">Prochaines séances</div>
          {upcomingSessions.length === 0 && <div className="empty-state">Aucune séance programmée pour l'instant.</div>}
          <div className="scouting-list" style={{ marginBottom: 20 }}>
            {upcomingSessions.map((s) => (
              <div className="scouting-card" key={s.id}>
                <div className="scouting-info">
                  <div className="scouting-name">{s.name}</div>
                  <div className="scouting-meta">{formatDateFr(s.date)}</div>
                </div>
              </div>
            ))}
          </div>

          <div className="panel-heading">Objectifs de développement</div>
          {objectives.length === 0 && <div className="empty-state">Aucun objectif enregistré pour l'instant.</div>}
          <div className="scouting-list" style={{ marginBottom: 20 }}>
            {objectives.map((o) => (
              <div className="scouting-card" key={o.id}>
                <div className="scouting-info">
                  <div className="scouting-name">{o.title} <span className="scouting-club">{o.status}</span></div>
                  {o.description && <div className="scouting-meta">{o.description}</div>}
                </div>
              </div>
            ))}
          </div>

          {playerPrograms.length > 0 && (
            <>
              <div className="panel-heading">Programme d'exercices individuel</div>
              <div className="scouting-list">
                {playerPrograms.map((p) => (
                  <div className="scouting-card" key={p.id}>
                    <div className="scouting-info">
                      <div className="scouting-name">{p.exerciseName}</div>
                      {p.frequency && <div className="scouting-meta">{p.frequency}</div>}
                    </div>
                  </div>
                ))}
              </div>
            </>
          )}
        </>
      )}
    </div>
  );
}

function ClubSponsorsScreen() {
  const [sponsors, setSponsors] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptySponsor());

  useEffect(() => {
    try { setSponsors(JSON.parse(localStorage.getItem("tf_club_sponsors") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setSponsors(next);
    try { localStorage.setItem("tf_club_sponsors", JSON.stringify(next)); } catch (e) { alert("La sauvegarde a échoué."); }
  }
  function openNew() { setForm(emptySponsor()); setEditingId(null); setShowForm(true); }
  function openEdit(s) { setForm({ ...emptySponsor(), ...s }); setEditingId(s.id); setShowForm(true); }
  function save() {
    if (!form.name.trim()) { alert("Donne un nom à ce sponsor/partenaire."); return; }
    if (editingId) persist(sponsors.map((s) => (s.id === editingId ? form : s)));
    else persist([...sponsors, form]);
    setShowForm(false);
  }
  function remove(id) {
    if (!confirm("Supprimer ce sponsor/partenaire ?")) return;
    persist(sponsors.filter((s) => s.id !== id));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const renewalsSoon = sponsors.filter((s) => isSponsorRenewalSoon(s.renewalDate));

  return (
    <div>
      <p className="radar-note">Sponsors et partenaires locaux — qui, quoi, échéance de renouvellement.</p>

      {renewalsSoon.length > 0 && (
        <div className="empty-state" style={{ borderColor: "var(--crimson)", marginBottom: 14 }}>
          {renewalsSoon.length} partenariat{renewalsSoon.length > 1 ? "s" : ""} à renouveler sous 60 jours (ou déjà expiré) — {renewalsSoon.map((s) => s.name).join(", ")}.
        </div>
      )}

      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Ajouter un sponsor/partenaire</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Nom<input type="text" value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} autoFocus /></label>
          <div className="roster-physical-grid">
            <label>Contact<input type="text" value={form.contactName} onChange={(e) => setForm((f) => ({ ...f, contactName: e.target.value }))} /></label>
            <label>Téléphone/email<input type="text" value={form.contactInfo} onChange={(e) => setForm((f) => ({ ...f, contactInfo: e.target.value }))} /></label>
          </div>
          <label>Type de contribution
            <select value={form.contributionType} onChange={(e) => setForm((f) => ({ ...f, contributionType: e.target.value }))}>
              {SPONSOR_CONTRIBUTION_TYPES.map((t) => <option key={t} value={t}>{t}</option>)}
            </select>
          </label>
          <label>Détail de la contribution<input type="text" placeholder="ex. 500€/saison, ou jeu de maillots" value={form.contribution} onChange={(e) => setForm((f) => ({ ...f, contribution: e.target.value }))} /></label>
          <div className="roster-physical-grid">
            <label>Début du partenariat<input type="date" value={form.startDate} onChange={(e) => setForm((f) => ({ ...f, startDate: e.target.value }))} /></label>
            <label>Échéance de renouvellement<input type="date" value={form.renewalDate} onChange={(e) => setForm((f) => ({ ...f, renewalDate: e.target.value }))} /></label>
          </div>
          <label>Notes<textarea rows={2} value={form.notes} onChange={(e) => setForm((f) => ({ ...f, notes: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => setShowForm(false)}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}

      {sponsors.length === 0 && <div className="empty-state">Aucun sponsor/partenaire enregistré pour l'instant.</div>}
      <div className="scouting-list">
        {sponsors.map((s) => (
          <div className="scouting-card" key={s.id} onClick={() => openEdit(s)} style={{ cursor: "pointer" }}>
            <div className="scouting-info">
              <div className="scouting-name">{s.name} <span className="scouting-club">{s.contributionType}</span></div>
              <div className="scouting-meta">{s.contribution || "Contribution non précisée"}</div>
              <div className="scouting-meta" style={isSponsorRenewalSoon(s.renewalDate) ? { color: "var(--crimson)" } : undefined}>
                {s.renewalDate ? `Renouvellement : ${formatDateFr(s.renewalDate)}` : "Aucune échéance renseignée"}
              </div>
            </div>
            <button className="icon-btn" onClick={(e) => { e.stopPropagation(); remove(s.id); }} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
      </div>
    </div>
  );
}

function ClubDuesScreen() {
  const [roster, setRoster] = useState([]);
  const [dues, setDues] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [filter, setFilter] = useState("impayes");
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState(emptyDuesRecord(""));

  useEffect(() => {
    try { setRoster(JSON.parse(localStorage.getItem("tf_roster") || "[]")); } catch (e) {}
    try { setDues(JSON.parse(localStorage.getItem("tf_club_dues") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setDues(next);
    try { localStorage.setItem("tf_club_dues", JSON.stringify(next)); } catch (e) { alert("La sauvegarde a échoué."); }
  }
  function openNew() { setForm(emptyDuesRecord(roster[0]?.id || "")); setShowForm(true); }
  function save() {
    if (!form.playerId) { alert("Choisis un joueur."); return; }
    if (!form.amount || form.amount <= 0) { alert("Indique un montant supérieur à 0."); return; }
    persist([...dues, form]);
    setShowForm(false);
  }
  function togglePaid(id) {
    persist(dues.map((d) => (d.id === id ? { ...d, paid: !d.paid, paidDate: !d.paid ? todayIso() : "" } : d)));
  }
  function remove(id) {
    if (!confirm("Supprimer cet appel de cotisation ?")) return;
    persist(dues.filter((d) => d.id !== id));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const filtered = filter === "tous" ? dues : filter === "payes" ? dues.filter((d) => d.paid) : dues.filter((d) => !d.paid);
  const totalDue = dues.filter((d) => !d.paid).reduce((s, d) => s + Number(d.amount || 0), 0);
  const totalPaid = dues.filter((d) => d.paid).reduce((s, d) => s + Number(d.amount || 0), 0);

  return (
    <div>
      <p className="radar-note">Suivi des cotisations par joueur — qui a payé, qui reste à relancer. {totalDue > 0 && `${totalDue}€ restant${totalDue !== 1 ? "s" : ""} à percevoir`}{totalDue > 0 && totalPaid > 0 ? ", " : ""}{totalPaid > 0 && `${totalPaid}€ déjà encaissé${totalPaid !== 1 ? "s" : ""}`}.</p>

      <div className="tabs" style={{ marginBottom: 14 }}>
        <button className={`tab ${filter === "impayes" ? "active" : ""}`} onClick={() => setFilter("impayes")}>Impayées ({dues.filter((d) => !d.paid).length})</button>
        <button className={`tab ${filter === "payes" ? "active" : ""}`} onClick={() => setFilter("payes")}>Payées ({dues.filter((d) => d.paid).length})</button>
        <button className={`tab ${filter === "tous" ? "active" : ""}`} onClick={() => setFilter("tous")}>Toutes ({dues.length})</button>
      </div>

      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Nouvel appel de cotisation</button>}
      {showForm && (
        <div className="new-match-card" style={{ marginBottom: 16 }}>
          <label>Joueur
            <select value={form.playerId} onChange={(e) => setForm((f) => ({ ...f, playerId: e.target.value }))}>
              <option value="">Choisir…</option>
              {roster.map((p) => <option key={p.id} value={p.id}>{playerFullName(p)}</option>)}
            </select>
          </label>
          <div className="roster-physical-grid">
            <label>Montant (€)<input type="number" min="0" step="0.01" value={form.amount} onChange={(e) => setForm((f) => ({ ...f, amount: Number(e.target.value) }))} /></label>
            <label>Échéance<input type="date" value={form.dueDate} onChange={(e) => setForm((f) => ({ ...f, dueDate: e.target.value }))} /></label>
          </div>
          <label>Notes (optionnel)<input type="text" value={form.notes} onChange={(e) => setForm((f) => ({ ...f, notes: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => setShowForm(false)}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}

      {filtered.length === 0 && <div className="empty-state">Aucune cotisation {filter === "impayes" ? "impayée" : filter === "payes" ? "payée" : "enregistrée"} pour l'instant.</div>}
      <div className="scouting-list">
        {filtered.map((d) => {
          const player = roster.find((p) => p.id === d.playerId);
          const late = !d.paid && new Date(d.dueDate) < new Date(todayIso());
          return (
            <div className="scouting-card" key={d.id}>
              <div className="scouting-info">
                <div className="scouting-name">{player ? playerFullName(player) : "Joueur non identifié"} <span className="scouting-club">{d.amount}€</span></div>
                <div className="scouting-meta" style={late ? { color: "var(--crimson)" } : undefined}>{d.paid ? `Payé le ${formatDateFr(d.paidDate)}` : `Échéance : ${formatDateFr(d.dueDate)}${late ? " — en retard" : ""}`}</div>
                {d.notes && <div className="scouting-meta">{d.notes}</div>}
              </div>
              <div style={{ display: "flex", gap: 6 }}>
                <button className="btn btn-ghost btn-small" onClick={() => togglePaid(d.id)}>{d.paid ? "Marquer impayée" : "Marquer payée"}</button>
                <button className="icon-btn" onClick={() => remove(d.id)} aria-label="Supprimer"><X size={14} /></button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function ClubTournamentsScreen() {
  const [tournaments, setTournaments] = useState([]);
  const [registrations, setRegistrations] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [tab, setTab] = useState("liste");
  const [showTournamentForm, setShowTournamentForm] = useState(false);
  const [tournamentForm, setTournamentForm] = useState(emptyTournament());
  const [registeringId, setRegisteringId] = useState(null);
  const [regForm, setRegForm] = useState(emptyTournamentRegistration(""));
  const [manageTournamentId, setManageTournamentId] = useState(null);

  async function refresh() {
    const [t, r] = await Promise.all([getAllTournaments(), getAllRegistrations()]);
    setTournaments(t);
    setRegistrations(r);
    setLoaded(true);
  }
  useEffect(() => { refresh(); }, []);

  async function handleSaveTournament() {
    if (!tournamentForm.name.trim()) { alert("Donne un nom à ce tournoi/événement."); return; }
    await saveTournament(tournamentForm);
    await refresh();
    setShowTournamentForm(false);
    setTournamentForm(emptyTournament());
  }
  async function handleRemoveTournament(id) {
    if (!confirm("Supprimer ce tournoi et toutes ses inscriptions ?")) return;
    await removeTournament(id);
    await refresh();
  }
  async function handleRegister() {
    if (!regForm.teamName.trim()) { alert("Indique le nom de ton équipe."); return; }
    await registerForTournament(regForm);
    await refresh();
    setRegisteringId(null);
    setRegForm(emptyTournamentRegistration(""));
  }
  async function handleSetRegStatus(id, status) {
    await setRegistrationStatus(id, status);
    await refresh();
  }
  async function handleRemoveReg(id) {
    if (!confirm("Retirer cette inscription ?")) return;
    await removeRegistration(id);
    await refresh();
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  if (manageTournamentId) {
    const t = tournaments.find((x) => x.id === manageTournamentId);
    if (!t) { setManageTournamentId(null); return null; }
    const regsForT = registrations.filter((r) => r.tournamentId === t.id);
    return (
      <div>
        <button className="btn btn-ghost btn-small" onClick={() => setManageTournamentId(null)} style={{ marginBottom: 14 }}>‹ Retour</button>
        <div className="panel-heading" style={{ marginTop: 0 }}>{t.name} — inscriptions ({regsForT.length}{t.maxTeams ? `/${t.maxTeams}` : ""})</div>
        {regsForT.length === 0 && <div className="empty-state">Aucune inscription pour l'instant.</div>}
        <div className="scouting-list">
          {regsForT.map((r) => (
            <div className="scouting-card" key={r.id}>
              <div className="scouting-info">
                <div className="scouting-name">{r.teamName} <span className="scouting-club">{REGISTRATION_STATUSES[r.status]}</span></div>
                <div className="scouting-meta">Contact : {r.contactName}{r.contactInfo ? ` · ${r.contactInfo}` : ""}</div>
              </div>
              {r.status === "en_attente" && (
                <div style={{ display: "flex", gap: 6 }}>
                  <button className="btn btn-ghost btn-small" onClick={() => handleSetRegStatus(r.id, "confirmee")}>Confirmer</button>
                  <button className="btn btn-ghost btn-small" onClick={() => handleSetRegStatus(r.id, "refusee")}>Refuser</button>
                </div>
              )}
              <button className="icon-btn" onClick={() => handleRemoveReg(r.id)} aria-label="Supprimer"><X size={14} /></button>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div>
      <p className="radar-note">Prototype pour tester l'intérêt d'une plateforme de matchs amicaux et tournois entre clubs — comme pour les arbitres, tout reste pour l'instant dans ton navigateur, pas encore une vraie mise en relation entre clubs différents (ça demanderait un vrai serveur).</p>

      <div className="tabs" style={{ marginBottom: 14 }}>
        <button className={`tab ${tab === "liste" ? "active" : ""}`} onClick={() => setTab("liste")}>Tournois disponibles ({tournaments.filter((t) => t.status === "ouvert").length})</button>
        <button className={`tab ${tab === "organises" ? "active" : ""}`} onClick={() => setTab("organises")}>Mes tournois organisés ({tournaments.length})</button>
      </div>

      {tab === "organises" && (
        <>
          {!showTournamentForm && <button className="btn btn-primary btn-large" onClick={() => setShowTournamentForm(true)} style={{ marginBottom: 16 }}>+ Organiser un tournoi/événement</button>}
          {showTournamentForm && (
            <div className="new-match-card" style={{ marginBottom: 16 }}>
              <label>Nom<input type="text" placeholder="ex. Tournoi de printemps U15" value={tournamentForm.name} onChange={(e) => setTournamentForm((f) => ({ ...f, name: e.target.value }))} autoFocus /></label>
              <label>Club organisateur<input type="text" value={tournamentForm.organizingClub} onChange={(e) => setTournamentForm((f) => ({ ...f, organizingClub: e.target.value }))} /></label>
              <div className="roster-physical-grid">
                <label>Date de début<input type="date" value={tournamentForm.startDate} onChange={(e) => setTournamentForm((f) => ({ ...f, startDate: e.target.value }))} /></label>
                <label>Date de fin<input type="date" value={tournamentForm.endDate} onChange={(e) => setTournamentForm((f) => ({ ...f, endDate: e.target.value }))} /></label>
              </div>
              <label>Lieu<input type="text" value={tournamentForm.location} onChange={(e) => setTournamentForm((f) => ({ ...f, location: e.target.value }))} /></label>
              <div className="roster-physical-grid">
                <label>Catégorie d'âge<input type="text" placeholder="ex. U15" value={tournamentForm.ageCategory} onChange={(e) => setTournamentForm((f) => ({ ...f, ageCategory: e.target.value }))} /></label>
                <label>Nombre d'équipes max<input type="number" min="2" value={tournamentForm.maxTeams} onChange={(e) => setTournamentForm((f) => ({ ...f, maxTeams: Number(e.target.value) }))} /></label>
              </div>
              <div className="form-actions">
                <button className="btn btn-ghost" onClick={() => setShowTournamentForm(false)}>Annuler</button>
                <button className="btn btn-primary" onClick={handleSaveTournament}>Créer</button>
              </div>
            </div>
          )}
          {tournaments.length === 0 && <div className="empty-state">Aucun tournoi organisé pour l'instant.</div>}
          <div className="scouting-list">
            {tournaments.map((t) => {
              const count = registrations.filter((r) => r.tournamentId === t.id).length;
              return (
                <div className="scouting-card" key={t.id} onClick={() => setManageTournamentId(t.id)} style={{ cursor: "pointer" }}>
                  <div className="scouting-info">
                    <div className="scouting-name">{t.name} <span className="scouting-club">{TOURNAMENT_STATUSES[t.status]}</span></div>
                    <div className="scouting-meta">{formatDateFr(t.startDate)}{t.endDate ? ` → ${formatDateFr(t.endDate)}` : ""}{t.location ? ` · ${t.location}` : ""}</div>
                    <div className="scouting-meta">{count} inscription{count !== 1 ? "s" : ""}{t.maxTeams ? `/${t.maxTeams}` : ""}</div>
                  </div>
                  <button className="icon-btn" onClick={(e) => { e.stopPropagation(); handleRemoveTournament(t.id); }} aria-label="Supprimer"><X size={14} /></button>
                </div>
              );
            })}
          </div>
        </>
      )}

      {tab === "liste" && (
        <div className="scouting-list">
          {tournaments.filter((t) => t.status === "ouvert").length === 0 && <div className="empty-state">Aucun tournoi ouvert aux inscriptions pour l'instant.</div>}
          {tournaments.filter((t) => t.status === "ouvert").map((t) => {
            const count = registrations.filter((r) => r.tournamentId === t.id).length;
            const full = t.maxTeams && count >= t.maxTeams;
            return (
              <div className="scouting-card" key={t.id} style={{ flexDirection: "column", alignItems: "stretch" }}>
                <div className="scouting-info">
                  <div className="scouting-name">{t.name}</div>
                  <div className="scouting-meta">{formatDateFr(t.startDate)}{t.endDate ? ` → ${formatDateFr(t.endDate)}` : ""}{t.location ? ` · ${t.location}` : ""}{t.ageCategory ? ` · ${t.ageCategory}` : ""}</div>
                  <div className="scouting-meta">Organisé par {t.organizingClub || "non précisé"} · {count} inscription{count !== 1 ? "s" : ""}{t.maxTeams ? `/${t.maxTeams}` : ""}{full ? " · complet" : ""}</div>
                </div>
                {!full && (
                  registeringId === t.id ? (
                    <div style={{ marginTop: 8 }}>
                      <label>Nom de ton équipe<input type="text" value={regForm.teamName} onChange={(e) => setRegForm((f) => ({ ...f, tournamentId: t.id, teamName: e.target.value }))} autoFocus /></label>
                      <label>Contact<input type="text" placeholder="Ton nom" value={regForm.contactName} onChange={(e) => setRegForm((f) => ({ ...f, contactName: e.target.value }))} /></label>
                      <label>Téléphone ou email<input type="text" value={regForm.contactInfo} onChange={(e) => setRegForm((f) => ({ ...f, contactInfo: e.target.value }))} /></label>
                      <div className="form-actions">
                        <button className="btn btn-ghost" onClick={() => setRegisteringId(null)}>Annuler</button>
                        <button className="btn btn-primary" onClick={handleRegister}>S'inscrire</button>
                      </div>
                    </div>
                  ) : (
                    <button className="btn btn-ghost btn-small" style={{ marginTop: 8, alignSelf: "flex-start" }} onClick={() => { setRegisteringId(t.id); setRegForm(emptyTournamentRegistration(t.id)); }}>S'inscrire</button>
                  )
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function ClubRefereesScreen() {
  const [referees, setReferees] = useState([]);
  const [proposals, setProposals] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [subTab, setSubTab] = useState("repertoire");
  const [showRefForm, setShowRefForm] = useState(false);
  const [refForm, setRefForm] = useState(emptyReferee());
  const [showProposalForm, setShowProposalForm] = useState(false);
  const [proposalForm, setProposalForm] = useState(emptyMatchProposal());
  const [respondingProposalId, setRespondingProposalId] = useState(null);
  const [respondingRefId, setRespondingRefId] = useState("");

  async function refresh() {
    const [refs, props] = await Promise.all([getAllReferees(), getProposals()]);
    setReferees(refs);
    setProposals(props);
    setLoaded(true);
  }
  useEffect(() => { refresh(); }, []);

  async function handleSaveReferee() {
    if (!refForm.name.trim()) { alert("Donne un nom à cet arbitre."); return; }
    await saveReferee(refForm);
    await refresh();
    setShowRefForm(false);
    setRefForm(emptyReferee());
  }
  async function handleRemoveReferee(id) {
    if (!confirm("Retirer cet arbitre du répertoire ?")) return;
    await removeReferee(id);
    await refresh();
  }
  async function handleCreateProposal() {
    if (!proposalForm.title.trim()) { alert("Donne un titre à cette proposition."); return; }
    if (!proposalForm.date) { alert("Choisis une date."); return; }
    await createProposal(proposalForm);
    await refresh();
    setShowProposalForm(false);
    setProposalForm(emptyMatchProposal());
  }
  async function handleRespond() {
    if (!respondingRefId) { alert("Choisis un arbitre."); return; }
    const ref = referees.find((r) => r.id === respondingRefId);
    if (!ref) return;
    await respondToProposal(respondingProposalId, ref.id, ref.name);
    await refresh();
    setRespondingProposalId(null);
    setRespondingRefId("");
  }
  async function handleSetStatus(id, status) {
    await setProposalStatus(id, status);
    await refresh();
  }
  async function handleRemoveProposal(id) {
    if (!confirm("Supprimer cette proposition ?")) return;
    await removeProposal(id);
    await refresh();
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Prototype pour tester l'intérêt d'une mise en relation d'arbitres entre clubs pour les amicaux/tournois hors désignation officielle. Utile pour te faire une idée du fonctionnement ou pour faire une démonstration à d'autres coachs — voir la remarque en bas de page sur ce que ça ne fait pas encore.</p>

      <div className="tabs" style={{ marginBottom: 14 }}>
        <button className={`tab ${subTab === "repertoire" ? "active" : ""}`} onClick={() => setSubTab("repertoire")}>Répertoire ({referees.length})</button>
        <button className={`tab ${subTab === "propositions" ? "active" : ""}`} onClick={() => setSubTab("propositions")}>Propositions de match ({proposals.length})</button>
      </div>

      {subTab === "repertoire" && (
        <>
          {!showRefForm && <button className="btn btn-primary btn-large" onClick={() => setShowRefForm(true)} style={{ marginBottom: 16 }}>+ Ajouter un arbitre</button>}
          {showRefForm && (
            <div className="new-match-card" style={{ marginBottom: 16 }}>
              <label>Nom<input type="text" value={refForm.name} onChange={(e) => setRefForm((f) => ({ ...f, name: e.target.value }))} autoFocus /></label>
              <label>Niveau
                <select value={refForm.level} onChange={(e) => setRefForm((f) => ({ ...f, level: e.target.value }))}>
                  {REFEREE_LEVELS.map((l) => <option key={l} value={l}>{l}</option>)}
                </select>
              </label>
              <label>Ville<input type="text" value={refForm.city} onChange={(e) => setRefForm((f) => ({ ...f, city: e.target.value }))} /></label>
              <label>Contact<input type="text" placeholder="Téléphone ou email" value={refForm.contact} onChange={(e) => setRefForm((f) => ({ ...f, contact: e.target.value }))} /></label>
              <label style={{ display: "block" }}>
                <input type="checkbox" checked={refForm.availableForExternal} onChange={(e) => setRefForm((f) => ({ ...f, availableForExternal: e.target.checked }))} style={{ marginRight: 6 }} />
                Disponible pour des propositions externes (amicaux, tournois)
              </label>
              <div className="form-actions">
                <button className="btn btn-ghost" onClick={() => setShowRefForm(false)}>Annuler</button>
                <button className="btn btn-primary" onClick={handleSaveReferee}>Enregistrer</button>
              </div>
            </div>
          )}
          {referees.length === 0 && <div className="empty-state">Aucun arbitre enregistré pour l'instant.</div>}
          <div className="scouting-list">
            {referees.map((r) => (
              <div className="scouting-card" key={r.id}>
                <div className="scouting-info">
                  <div className="scouting-name">{r.name} <span className="scouting-club">{r.level}</span></div>
                  <div className="scouting-meta">{r.city}{r.contact ? ` · ${r.contact}` : ""}</div>
                  <div className="scouting-meta">{r.availableForExternal ? "Disponible pour propositions externes" : "Non disponible en externe"}</div>
                </div>
                <button className="icon-btn" onClick={() => handleRemoveReferee(r.id)} aria-label="Supprimer"><X size={14} /></button>
              </div>
            ))}
          </div>
        </>
      )}

      {subTab === "propositions" && (
        <>
          {!showProposalForm && <button className="btn btn-primary btn-large" onClick={() => setShowProposalForm(true)} style={{ marginBottom: 16 }}>+ Nouvelle proposition</button>}
          {showProposalForm && (
            <div className="new-match-card" style={{ marginBottom: 16 }}>
              <label>Titre<input type="text" placeholder="ex. Tournoi U15 du 12 octobre" value={proposalForm.title} onChange={(e) => setProposalForm((f) => ({ ...f, title: e.target.value }))} autoFocus /></label>
              <div className="roster-physical-grid">
                <label>Date<input type="date" value={proposalForm.date} onChange={(e) => setProposalForm((f) => ({ ...f, date: e.target.value }))} /></label>
                <label>Lieu<input type="text" value={proposalForm.location} onChange={(e) => setProposalForm((f) => ({ ...f, location: e.target.value }))} /></label>
              </div>
              <label>Niveau requis
                <select value={proposalForm.levelRequired} onChange={(e) => setProposalForm((f) => ({ ...f, levelRequired: e.target.value }))}>
                  {REFEREE_LEVELS.map((l) => <option key={l} value={l}>{l}</option>)}
                </select>
              </label>
              <div className="form-actions">
                <button className="btn btn-ghost" onClick={() => setShowProposalForm(false)}>Annuler</button>
                <button className="btn btn-primary" onClick={handleCreateProposal}>Créer</button>
              </div>
            </div>
          )}
          {proposals.length === 0 && <div className="empty-state">Aucune proposition pour l'instant.</div>}
          <div className="scouting-list">
            {proposals.map((p) => (
              <div className="scouting-card" key={p.id} style={{ flexDirection: "column", alignItems: "stretch" }}>
                <div className="scouting-info">
                  <div className="scouting-name">{p.title} <span className="scouting-club">{PROPOSAL_STATUSES[p.status]}</span></div>
                  <div className="scouting-meta">{formatDateFr(p.date)}{p.location ? ` · ${p.location}` : ""} · Niveau {p.levelRequired}</div>
                  <div className="scouting-meta">{p.responses.length} arbitre{p.responses.length !== 1 ? "s" : ""} intéressé{p.responses.length !== 1 ? "s" : ""}{p.responses.length > 0 ? ` : ${p.responses.map((r) => r.refereeName).join(", ")}` : ""}</div>
                </div>
                {p.status === "open" && (
                  <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 8, alignItems: "center" }}>
                    {respondingProposalId === p.id ? (
                      <>
                        <select value={respondingRefId} onChange={(e) => setRespondingRefId(e.target.value)}>
                          <option value="">Choisir un arbitre…</option>
                          {referees.filter((r) => r.availableForExternal).map((r) => <option key={r.id} value={r.id}>{r.name}</option>)}
                        </select>
                        <button className="btn btn-ghost btn-small" onClick={handleRespond}>Confirmer l'intérêt</button>
                        <button className="btn btn-ghost btn-small" onClick={() => setRespondingProposalId(null)}>Annuler</button>
                      </>
                    ) : (
                      <button className="btn btn-ghost btn-small" onClick={() => setRespondingProposalId(p.id)}>Simuler une réponse d'arbitre</button>
                    )}
                    <button className="btn btn-ghost btn-small" onClick={() => handleSetStatus(p.id, "filled")}>Marquer pourvue</button>
                    <button className="btn btn-ghost btn-small" onClick={() => handleSetStatus(p.id, "cancelled")}>Annuler la proposition</button>
                  </div>
                )}
                <button className="icon-btn" style={{ alignSelf: "flex-end", marginTop: 6 }} onClick={() => handleRemoveProposal(p.id)} aria-label="Supprimer">
                  <X size={14} />
                </button>
              </div>
            ))}
          </div>
        </>
      )}

      <p className="hint" style={{ marginTop: 20 }}>Rappel : comme le Forum, ceci reste pour l'instant dans ton propre navigateur — utile pour se faire une idée ou faire une démonstration, mais pas encore une vraie mise en relation entre des clubs différents (ça demanderait un vrai serveur).</p>
    </div>
  );
}

function ClubStaffScreen({ teams }) {
  const [staff, setStaff] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyStaffMember());
  const [loaded, setLoaded] = useState(false);
  const [staffTab, setStaffTab] = useState("coaching");
  const [rolePickValue, setRolePickValue] = useState("");

  useEffect(() => {
    try { setStaff(JSON.parse(window.localStorage.getItem("tf_club_staff") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setStaff(next);
    try { window.localStorage.setItem("tf_club_staff", JSON.stringify(next)); } catch (e) { alert("La sauvegarde a échoué."); }
  }
  function openNew() { setForm(emptyStaffMember()); setEditingId(null); setShowForm(true); setRolePickValue(""); }
  function openEdit(s) { setForm({ ...emptyStaffMember(), ...s, roles: staffRoles(s) }); setEditingId(s.id); setShowForm(true); setRolePickValue(""); }
  function save() {
    if (!form.firstName.trim() && !form.lastName.trim()) { alert("Renseigne au moins un nom."); return; }
    if (form.roles.length === 0) { alert("Choisis au moins un rôle."); return; }
    if (editingId) persist(staff.map((s) => (s.id === editingId ? form : s)));
    else persist([...staff, form]);
    setShowForm(false);
  }
  function remove(id) {
    if (!confirm("Supprimer cette fiche du staff ?")) return;
    persist(staff.filter((s) => s.id !== id));
  }
  function toggleTeam(teamId) {
    setForm((f) => ({ ...f, teamIds: f.teamIds.includes(teamId) ? f.teamIds.filter((x) => x !== teamId) : [...f.teamIds, teamId] }));
  }
  function addRole() {
    if (!rolePickValue) return;
    setForm((f) => (f.roles.includes(rolePickValue) ? f : { ...f, roles: [...f.roles, rolePickValue] }));
    setRolePickValue("");
  }
  function removeRole(role) {
    setForm((f) => ({ ...f, roles: f.roles.filter((r) => r !== role) }));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const expiring = staff.filter((s) => isDiplomaExpiringSoon(s.diplomaExpiry));
  const notVerified = staff.filter((s) => !s.honorabiliteVerifiee);

  return (
    <div>
      <p className="radar-note">Répertoire du staff du club — chaque membre peut être rattaché à une ou plusieurs équipes. Sert de base aux autres fonctionnalités club (formations, créneaux, comptes-rendus...).</p>

      {expiring.length > 0 && (
        <div className="empty-state" style={{ borderColor: "var(--crimson)", marginBottom: 14 }}>
          {expiring.length} diplôme{expiring.length > 1 ? "s" : ""} expiré{expiring.length > 1 ? "s" : ""} ou à renouveler sous 60 jours — {expiring.map((s) => `${s.firstName} ${s.lastName}`).join(", ")}.
        </div>
      )}
      {notVerified.length > 0 && (
        <div className="empty-state" style={{ borderColor: "var(--crimson)", marginBottom: 14 }}>
          {notVerified.length} membre{notVerified.length > 1 ? "s" : ""} du staff sans contrôle d'honorabilité enregistré — {notVerified.map((s) => `${s.firstName} ${s.lastName}`).join(", ")}.
        </div>
      )}

      {!showForm && <button className="btn btn-primary btn-large" onClick={openNew} style={{ marginBottom: 16 }}>+ Ajouter un membre du staff</button>}

      {showForm && (
        <div className="new-match-card">
          <div className="roster-physical-grid">
            <label>Prénom<input type="text" value={form.firstName} onChange={(e) => setForm((f) => ({ ...f, firstName: e.target.value }))} /></label>
            <label>Nom<input type="text" value={form.lastName} onChange={(e) => setForm((f) => ({ ...f, lastName: e.target.value }))} /></label>
          </div>
          <label>Rôle(s)
            <div style={{ display: "flex", gap: 8 }}>
              <select value={rolePickValue} onChange={(e) => setRolePickValue(e.target.value)} style={{ flex: 1 }}>
                <option value="">Choisir un rôle à ajouter…</option>
                {STAFF_FUNCTION_GROUPS.map((g) => (
                  <optgroup key={g.key} label={g.label}>
                    {g.roles.filter((r) => !form.roles.includes(r)).map((r) => <option key={r} value={r}>{r}</option>)}
                  </optgroup>
                ))}
              </select>
              <button type="button" className="btn btn-ghost btn-small" onClick={addRole}>+ Ajouter</button>
            </div>
          </label>
          {form.roles.length > 0 && (
            <div className="qcm-options" style={{ marginTop: 6 }}>
              {form.roles.map((r) => (
                <button key={r} type="button" className="qcm-option selected" onClick={() => removeRole(r)}>{r} ✕</button>
              ))}
            </div>
          )}
          <div className="radar-range-label">Équipe(s) encadrée(s)</div>
          <div className="qcm-options">
            {teams.map((t) => (
              <button key={t.id} className={`qcm-option ${form.teamIds.includes(t.id) ? "selected" : ""}`} onClick={() => toggleTeam(t.id)}>{t.name}</button>
            ))}
          </div>
          <div className="roster-physical-grid">
            <label>Email<input type="email" value={form.email} onChange={(e) => setForm((f) => ({ ...f, email: e.target.value }))} /></label>
            <label>Téléphone<input type="text" value={form.phone} onChange={(e) => setForm((f) => ({ ...f, phone: e.target.value }))} /></label>
          </div>
          <div className="roster-physical-grid">
            <label>Diplômes<input type="text" placeholder="ex. BMF, DEF" value={form.diplomas} onChange={(e) => setForm((f) => ({ ...f, diplomas: e.target.value }))} /></label>
            <label>Expiration/renouvellement<input type="date" value={form.diplomaExpiry} onChange={(e) => setForm((f) => ({ ...f, diplomaExpiry: e.target.value }))} /></label>
          </div>
          <label style={{ display: "block", marginTop: 8 }}>
            <input type="checkbox" checked={form.honorabiliteVerifiee} onChange={(e) => setForm((f) => ({ ...f, honorabiliteVerifiee: e.target.checked, honorabiliteDate: e.target.checked ? (f.honorabiliteDate || todayIso()) : f.honorabiliteDate }))} style={{ marginRight: 6 }} />
            Contrôle d'honorabilité effectué (protection des mineurs)
          </label>
          {form.honorabiliteVerifiee && (
            <label>Date de vérification<input type="date" value={form.honorabiliteDate} onChange={(e) => setForm((f) => ({ ...f, honorabiliteDate: e.target.value }))} /></label>
          )}
          <label>Notes<textarea rows={2} value={form.notes} onChange={(e) => setForm((f) => ({ ...f, notes: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => setShowForm(false)}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer</button>
          </div>
        </div>
      )}

      <div className="tabs" style={{ marginTop: 16 }}>
        {STAFF_FUNCTION_GROUPS.map((g) => (
          <button key={g.key} className={`tab ${staffTab === g.key ? "active" : ""}`} onClick={() => setStaffTab(g.key)}>
            {g.label} <span className="scouting-club">({staff.filter((s) => staffMemberInGroup(s, g.key)).length})</span>
          </button>
        ))}
      </div>

      <div className="roster-grid" style={{ marginTop: 12 }}>
        {staff.length === 0 && <div className="empty-state">Aucun membre du staff enregistré pour l'instant.</div>}
        {staff.length > 0 && staff.filter((s) => staffMemberInGroup(s, staffTab)).length === 0 && (
          <div className="empty-state">Personne en « {STAFF_FUNCTION_GROUPS.find((g) => g.key === staffTab)?.label} » pour l'instant.</div>
        )}
        {staff.filter((s) => staffMemberInGroup(s, staffTab)).map((s) => (
          <div className="roster-card" key={s.id} onClick={() => openEdit(s)} style={{ cursor: "pointer" }}>
            <div className="roster-card-info">
              <div className="roster-card-name">{s.firstName} {s.lastName}</div>
              <div className="roster-card-position">{staffRoles(s).join(", ")}</div>
              <div className="roster-card-usage">
                {s.teamIds.map((tid) => teams.find((t) => t.id === tid)).filter(Boolean).map((t) => t.name).join(", ") || "Aucune équipe rattachée"}
              </div>
              {s.diplomas && (
                <div className="roster-card-meta" style={isDiplomaExpiringSoon(s.diplomaExpiry) ? { color: "var(--crimson)" } : undefined}>
                  {s.diplomas}{s.diplomaExpiry ? ` — renouvellement le ${formatDateFr(s.diplomaExpiry)}` : ""}
                </div>
              )}
              <div className="roster-card-meta" style={!s.honorabiliteVerifiee ? { color: "var(--crimson)" } : undefined}>
                {s.honorabiliteVerifiee ? `Honorabilité vérifiée le ${formatDateFr(s.honorabiliteDate)}` : "Contrôle d'honorabilité non renseigné"}
              </div>
            </div>
            <div className="roster-card-actions">
              <button className="icon-btn" onClick={(e) => { e.stopPropagation(); remove(s.id); }} aria-label="Supprimer"><X size={14} /></button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

function emptySportingProject() {
  return { vision: "", horizonYears: 3, objectives: [] };
}
function emptyProjectObjective(year) {
  return { id: newId(), year: year || new Date().getFullYear(), title: "", description: "", status: "À venir" };
}
const PROJECT_OBJECTIVE_STATUSES = ["À venir", "En cours", "Atteint", "Reporté"];

function SportingProjectScreen() {
  const [data, setData] = useState(emptySportingProject());
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setData({ ...emptySportingProject(), ...JSON.parse(window.localStorage.getItem("tf_club_sporting_project") || "{}") }); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setData(next);
    try { window.localStorage.setItem("tf_club_sporting_project", JSON.stringify(next)); } catch (e) {}
  }
  function addObjective() {
    persist({ ...data, objectives: [...data.objectives, emptyProjectObjective(new Date().getFullYear())] });
  }
  function updateObjective(id, field, value) {
    persist({ ...data, objectives: data.objectives.map((o) => (o.id === id ? { ...o, [field]: value } : o)) });
  }
  function removeObjective(id) {
    if (!confirm("Supprimer cet objectif ?")) return;
    persist({ ...data, objectives: data.objectives.filter((o) => o.id !== id) });
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">La direction générale du club sur plusieurs saisons — sert de fil conducteur aux projets de jeu de chaque équipe, sans les remplacer.</p>
      <div className="new-match-card">
        <label>Vision générale<textarea rows={3} placeholder="ex. Devenir une référence régionale de formation, avec un jeu offensif et une identité claire du gardien à l'attaquant." value={data.vision} onChange={(e) => persist({ ...data, vision: e.target.value })} /></label>
        <label>Horizon (années)<input type="number" min="1" max="10" value={data.horizonYears} onChange={(e) => persist({ ...data, horizonYears: Number(e.target.value) })} /></label>
      </div>

      <div className="panel-heading" style={{ marginTop: 20 }}>Objectifs par échéance</div>
      <div className="scouting-list">
        {data.objectives.sort((a, b) => a.year - b.year).map((o) => (
          <div className="scouting-card" key={o.id} style={{ flexWrap: "wrap" }}>
            <div className="scouting-info">
              <div className="roster-physical-grid">
                <label>Année<input type="number" value={o.year} onChange={(e) => updateObjective(o.id, "year", Number(e.target.value))} /></label>
                <label>Statut
                  <select value={o.status} onChange={(e) => updateObjective(o.id, "status", e.target.value)}>
                    {PROJECT_OBJECTIVE_STATUSES.map((s) => <option key={s} value={s}>{s}</option>)}
                  </select>
                </label>
              </div>
              <label>Titre<input type="text" value={o.title} onChange={(e) => updateObjective(o.id, "title", e.target.value)} /></label>
              <label>Description<textarea rows={2} value={o.description} onChange={(e) => updateObjective(o.id, "description", e.target.value)} /></label>
            </div>
            <button className="icon-btn" onClick={() => removeObjective(o.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
        {data.objectives.length === 0 && <div className="empty-state">Aucun objectif renseigné pour l'instant.</div>}
      </div>
      <button className="btn btn-ghost btn-small" onClick={addObjective} style={{ marginTop: 10 }}>+ Ajouter un objectif</button>
    </div>
  );
}

function emptyClubGameIdentity() {
  return { visionGlobale: "", declinaisons: [] };
}
function emptyDeclinaison(category) {
  return { id: newId(), category: category || "", adaptation: "" };
}

function ClubGameIdentityScreen({ teams }) {
  const [data, setData] = useState(emptyClubGameIdentity());
  const [newCategory, setNewCategory] = useState("");
  const [loaded, setLoaded] = useState(false);
  const knownCategories = [...new Set(teams.map((t) => t.category).filter(Boolean))];

  useEffect(() => {
    try { setData({ ...emptyClubGameIdentity(), ...JSON.parse(window.localStorage.getItem("tf_club_identity") || "{}") }); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setData(next);
    try { window.localStorage.setItem("tf_club_identity", JSON.stringify(next)); } catch (e) {}
  }
  function addDeclinaison(category) {
    if (!category || data.declinaisons.some((d) => d.category === category)) return;
    persist({ ...data, declinaisons: [...data.declinaisons, emptyDeclinaison(category)] });
    setNewCategory("");
  }
  function updateDeclinaison(id, value) {
    persist({ ...data, declinaisons: data.declinaisons.map((d) => (d.id === id ? { ...d, adaptation: value } : d)) });
  }
  function removeDeclinaison(id) {
    persist({ ...data, declinaisons: data.declinaisons.filter((d) => d.id !== id) });
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Une philosophie de jeu commune au club, déclinée par catégorie d'âge — chaque équipe garde son propre Projet de jeu détaillé, celui-ci n'est qu'un fil conducteur partagé.</p>
      <div className="new-match-card">
        <label>Identité de jeu globale du club<textarea rows={3} placeholder="ex. Un club qui joue vers l'avant, privilégie la construction courte et la prise d'initiative individuelle, adaptée au niveau de chaque catégorie." value={data.visionGlobale} onChange={(e) => persist({ ...data, visionGlobale: e.target.value })} /></label>
      </div>

      <div className="panel-heading" style={{ marginTop: 20 }}>Déclinaisons par catégorie</div>
      <div className="scouting-list">
        {data.declinaisons.map((d) => (
          <div className="scouting-card" key={d.id}>
            <div className="scouting-info">
              <div className="scouting-name">{d.category}</div>
              <textarea rows={2} placeholder="Comment cette identité s'adapte à cette catégorie…" value={d.adaptation} onChange={(e) => updateDeclinaison(d.id, e.target.value)} />
            </div>
            <button className="icon-btn" onClick={() => removeDeclinaison(d.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
        {data.declinaisons.length === 0 && <div className="empty-state">Aucune déclinaison renseignée pour l'instant.</div>}
      </div>
      <div className="home-actions-row" style={{ marginTop: 10, flexWrap: "wrap" }}>
        {knownCategories.filter((c) => !data.declinaisons.some((d) => d.category === c)).map((c) => (
          <button key={c} className="btn btn-ghost btn-small" onClick={() => addDeclinaison(c)}>+ {c}</button>
        ))}
        <input type="text" placeholder="Autre catégorie…" value={newCategory} onChange={(e) => setNewCategory(e.target.value)} style={{ width: 160 }} />
        <button className="btn btn-ghost btn-small" onClick={() => addDeclinaison(newCategory.trim())}>+ Ajouter</button>
      </div>
    </div>
  );
}

const PEDAGOGY_THEMES = [
  { key: "technique", label: "Technique" },
  { key: "tactique", label: "Tactique" },
  { key: "physique", label: "Physique" },
  { key: "mental", label: "Mental" },
];
function emptyPedagogyEntry(category) {
  return { id: newId(), category: category || "", technique: "", tactique: "", physique: "", mental: "" };
}

function PedagogyReferenceScreen({ teams }) {
  const [entries, setEntries] = useState([]);
  const [newCategory, setNewCategory] = useState("");
  const [loaded, setLoaded] = useState(false);
  const knownCategories = [...new Set(teams.map((t) => t.category).filter(Boolean))];

  useEffect(() => {
    try { setEntries(JSON.parse(window.localStorage.getItem("tf_club_pedagogy") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setEntries(next);
    try { window.localStorage.setItem("tf_club_pedagogy", JSON.stringify(next)); } catch (e) {}
  }
  function addEntry(category) {
    if (!category || entries.some((e) => e.category === category)) return;
    persist([...entries, emptyPedagogyEntry(category)]);
    setNewCategory("");
  }
  function updateEntry(id, field, value) {
    persist(entries.map((e) => (e.id === id ? { ...e, [field]: value } : e)));
  }
  function removeEntry(id) {
    if (!confirm("Supprimer ce référentiel ?")) return;
    persist(entries.filter((e) => e.id !== id));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Ce qui doit être travaillé en priorité à chaque catégorie d'âge, par thème — la cohérence de formation du club dans le temps.</p>
      {entries.map((entry) => (
        <div key={entry.id} style={{ marginBottom: 20 }}>
          <div className="range-filter-header">
            <div className="panel-heading" style={{ marginBottom: 0 }}>{entry.category}</div>
            <button className="icon-btn" onClick={() => removeEntry(entry.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
          <div className="roster-physical-grid">
            {PEDAGOGY_THEMES.map((t) => (
              <label key={t.key}>{t.label}<textarea rows={2} value={entry[t.key]} onChange={(e) => updateEntry(entry.id, t.key, e.target.value)} /></label>
            ))}
          </div>
        </div>
      ))}
      {entries.length === 0 && <div className="empty-state">Aucun référentiel renseigné pour l'instant.</div>}
      <div className="home-actions-row" style={{ marginTop: 10, flexWrap: "wrap" }}>
        {knownCategories.filter((c) => !entries.some((e) => e.category === c)).map((c) => (
          <button key={c} className="btn btn-ghost btn-small" onClick={() => addEntry(c)}>+ {c}</button>
        ))}
        <input type="text" placeholder="Autre catégorie…" value={newCategory} onChange={(e) => setNewCategory(e.target.value)} style={{ width: 160 }} />
        <button className="btn btn-ghost btn-small" onClick={() => addEntry(newCategory.trim())}>+ Ajouter</button>
      </div>
    </div>
  );
}

function emptyPasserelle() {
  return { id: newId(), fromCategory: "", toCategory: "", criteria: "", notes: "" };
}

function PasserellesScreen({ teams }) {
  const [rules, setRules] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const knownCategories = [...new Set(teams.map((t) => t.category).filter(Boolean))];

  useEffect(() => {
    try { setRules(JSON.parse(window.localStorage.getItem("tf_club_passerelles") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setRules(next);
    try { window.localStorage.setItem("tf_club_passerelles", JSON.stringify(next)); } catch (e) {}
  }
  function addRule() {
    persist([...rules, emptyPasserelle()]);
  }
  function updateRule(id, field, value) {
    persist(rules.map((r) => (r.id === id ? { ...r, [field]: value } : r)));
  }
  function removeRule(id) {
    if (!confirm("Supprimer cette règle ?")) return;
    persist(rules.filter((r) => r.id !== id));
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Les critères qui justifient de faire monter un joueur d'une catégorie à l'autre — utile pour objectiver la décision et l'expliquer aux familles.</p>
      <div className="scouting-list">
        {rules.map((r) => (
          <div className="scouting-card" key={r.id} style={{ flexWrap: "wrap" }}>
            <div className="scouting-info">
              <div className="roster-physical-grid">
                <label>De la catégorie
                  <input type="text" list="passerelle-categories" placeholder="ex. U13" value={r.fromCategory} onChange={(e) => updateRule(r.id, "fromCategory", e.target.value)} />
                </label>
                <label>Vers la catégorie
                  <input type="text" list="passerelle-categories" placeholder="ex. U15" value={r.toCategory} onChange={(e) => updateRule(r.id, "toCategory", e.target.value)} />
                </label>
              </div>
              <datalist id="passerelle-categories">{knownCategories.map((c) => <option key={c} value={c} />)}</datalist>
              <label>Critères<textarea rows={2} placeholder="ex. Niveau technique et physique au-dessus de la moyenne de sa catégorie, maturité comportementale validée par le staff." value={r.criteria} onChange={(e) => updateRule(r.id, "criteria", e.target.value)} /></label>
              <label>Notes<input type="text" value={r.notes} onChange={(e) => updateRule(r.id, "notes", e.target.value)} /></label>
            </div>
            <button className="icon-btn" onClick={() => removeRule(r.id)} aria-label="Supprimer"><X size={14} /></button>
          </div>
        ))}
        {rules.length === 0 && <div className="empty-state">Aucune règle de passerelle renseignée pour l'instant.</div>}
      </div>
      <button className="btn btn-ghost btn-small" onClick={addRule} style={{ marginTop: 10 }}>+ Ajouter une règle</button>
    </div>
  );
}

function ClubOverviewTable({ teams }) {
  const [rows, setRows] = useState(null);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const seasonId = getActiveSeasonId();
      const results = await Promise.all(teams.map(async (t) => {
        const roster = (() => { try { return JSON.parse(readScopedKeyFor("tf_roster", t.id, seasonId) || "[]"); } catch (e) { return []; } })();
        const injuries = (() => { try { return JSON.parse(readScopedKeyFor("tf_medical_injuries", t.id, seasonId) || "[]"); } catch (e) { return []; } })();
        const activeInjuries = injuries.filter((i) => i.status === "en cours").length;
        const matchSummary = await readTeamMatchesSummary(t.id, seasonId);
        return { team: t, roster: roster.length, activeInjuries, ...matchSummary };
      }));
      if (!cancelled) setRows(results);
    })();
    return () => { cancelled = true; };
  }, [teams]);

  if (!rows) return <div className="empty-state">Chargement…</div>;

  return (
    <div className="table-scroll">
      <table className="stat-table">
        <thead><tr><th>Équipe</th><th>Effectif</th><th>Matchs</th><th>V-N-D</th><th>Cartons</th><th>Blessures actives</th></tr></thead>
        <tbody>
          {rows.map((r) => (
            <tr key={r.team.id}>
              <td>{r.team.name}</td>
              <td>{r.roster}</td>
              <td>{r.played}</td>
              <td>{r.wins}-{r.draws}-{r.losses}</td>
              <td>{r.cartons}</td>
              <td>{r.activeInjuries}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function ClubMedicalOverviewScreen({ teams }) {
  const [rows, setRows] = useState(null);

  useEffect(() => {
    const seasonId = getActiveSeasonId();
    const results = teams.map((t) => {
      const injuries = (() => { try { return JSON.parse(readScopedKeyFor("tf_medical_injuries", t.id, seasonId) || "[]"); } catch (e) { return []; } })();
      const byCategory = {};
      injuries.forEach((i) => { byCategory[i.category] = (byCategory[i.category] || 0) + 1; });
      const topCategory = Object.entries(byCategory).sort((a, b) => b[1] - a[1])[0];
      return {
        team: t,
        total: injuries.length,
        active: injuries.filter((i) => i.status === "en cours").length,
        topCategory: topCategory ? `${topCategory[0]} (${topCategory[1]})` : "—",
      };
    });
    setRows(results);
  }, [teams]);

  if (!rows) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Vue croisée des blessures par équipe — utile pour repérer si une catégorie d'âge est particulièrement touchée et ajuster les charges d'entraînement au niveau du club.</p>
      <div className="table-scroll">
        <table className="stat-table">
          <thead><tr><th>Équipe</th><th>Blessures (saison)</th><th>En cours</th><th>Catégorie la plus fréquente</th></tr></thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.team.id}><td>{r.team.name}</td><td>{r.total}</td><td>{r.active}</td><td>{r.topCategory}</td></tr>
            ))}
          </tbody>
        </table>
      </div>
      {rows.every((r) => r.total === 0) && <div className="empty-state" style={{ marginTop: 12 }}>Aucune blessure enregistrée dans aucune équipe pour l'instant.</div>}
    </div>
  );
}

function ClubExerciseLibraryScreen({ teams }) {
  const [exercises, setExercises] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState(emptyExerciseForm());
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setExercises(JSON.parse(window.localStorage.getItem("tf_club_exercise_library") || "[]")); } catch (e) {}
    setLoaded(true);
  }, []);

  function persist(next) {
    setExercises(next);
    try { window.localStorage.setItem("tf_club_exercise_library", JSON.stringify(next)); } catch (e) { alert("La sauvegarde a échoué."); }
  }
  function addExercise() {
    if (!form.name.trim()) { alert("Donne un nom à cet exercice."); return; }
    persist([...exercises, { ...form, id: newId() }]);
    setForm(emptyExerciseForm());
    setShowForm(false);
  }
  function removeExercise(id) {
    if (!confirm("Retirer cet exercice de la bibliothèque du club ?")) return;
    persist(exercises.filter((ex) => ex.id !== id));
  }
  function copyToActiveTeam(ex) {
    try {
      const current = JSON.parse(window.localStorage.getItem("tf_exercices") || "[]");
      window.localStorage.setItem("tf_exercices", JSON.stringify([...current, { ...ex, id: newId(), gameplanSection: "", gameplanChoice: "" }]));
      alert(`"${ex.name}" copié dans la banque d'exercices de l'équipe active — retrouve-le dans Séance → Banque générale.`);
    } catch (e) {
      alert("La copie a échoué.");
    }
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  return (
    <div>
      <p className="radar-note">Exercices partagés entre toutes les équipes du club. "Copier vers mon équipe" duplique l'exercice dans la banque de l'équipe actuellement active, pour l'utiliser dans une séance.</p>
      {!showForm && <button className="btn btn-primary btn-small" onClick={() => setShowForm(true)} style={{ marginBottom: 14 }}>+ Ajouter un exercice au club</button>}
      {showForm && (
        <div className="new-match-card">
          <label>Nom<input type="text" value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} /></label>
          <label>Objectif<input type="text" value={form.objectif} onChange={(e) => setForm((f) => ({ ...f, objectif: e.target.value }))} /></label>
          <div className="roster-physical-grid">
            <label>Durée (min)<input type="number" value={form.duree} onChange={(e) => setForm((f) => ({ ...f, duree: Number(e.target.value) }))} /></label>
            <label>Nombre de joueurs<input type="text" value={form.nbJoueurs} onChange={(e) => setForm((f) => ({ ...f, nbJoueurs: e.target.value }))} /></label>
          </div>
          <label>Matériel<input type="text" value={form.materiel} onChange={(e) => setForm((f) => ({ ...f, materiel: e.target.value }))} /></label>
          <label>Description<textarea rows={3} value={form.description} onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))} /></label>
          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => { setShowForm(false); setForm(emptyExerciseForm()); }}>Annuler</button>
            <button className="btn btn-primary" onClick={addExercise}>Ajouter</button>
          </div>
        </div>
      )}
      <div className="roster-grid" style={{ marginTop: 16 }}>
        {exercises.length === 0 && <div className="empty-state">Aucun exercice partagé pour l'instant — ajoutes-en ici, ou depuis Séance → Banque générale d'une équipe avec "Partager au club".</div>}
        {exercises.map((ex) => (
          <ExerciseCard
            key={ex.id}
            ex={ex}
            actions={<>
              <button className="btn btn-ghost btn-small" onClick={() => copyToActiveTeam(ex)}>Copier vers mon équipe</button>
              <button className="icon-btn" onClick={() => removeExercise(ex.id)} aria-label="Retirer"><X size={14} /></button>
            </>}
          />
        ))}
      </div>
    </div>
  );
}

function ClubVideothequeScreen({ teams }) {
  const [clips, setClips] = useState([]);
  const [clipUrls, setClipUrls] = useState({});
  const [loaded, setLoaded] = useState(false);
  const [staff, setStaff] = useState([]);
  const [assigneeFilter, setAssigneeFilter] = useState("");
  const [statusFilter, setStatusFilter] = useState("");

  useEffect(() => {
    getAllClubClips().then((all) => {
      setClips(all.sort((a, b) => b.createdAt - a.createdAt));
      const urls = {};
      all.forEach((c) => { urls[c.id] = URL.createObjectURL(c.blob); });
      setClipUrls(urls);
      setLoaded(true);
    }).catch(() => setLoaded(true));
    try { setStaff(JSON.parse(window.localStorage.getItem("tf_club_staff") || "[]")); } catch (e) {}
  }, []);

  function remove(id) {
    if (!confirm("Retirer ce clip de la vidéothèque du club ?")) return;
    deleteClubClip(id).then(() => setClips((prev) => prev.filter((c) => c.id !== id)));
  }
  function setAssignee(id, staffId) {
    setClips((prev) => prev.map((c) => (c.id === id ? { ...c, assignedTo: staffId } : c)));
    updateClipField(openClubClipsDB, id, "assignedTo", staffId);
  }
  function setStatus(id, status) {
    setClips((prev) => prev.map((c) => (c.id === id ? { ...c, status } : c)));
    updateClipField(openClubClipsDB, id, "status", status);
  }
  function setNote(id, note) {
    setClips((prev) => prev.map((c) => (c.id === id ? { ...c, note } : c)));
    updateClipField(openClubClipsDB, id, "note", note);
  }

  if (!loaded) return <div className="empty-state">Chargement…</div>;

  const filtered = clips.filter((c) => (!assigneeFilter || c.assignedTo === assigneeFilter) && (!statusFilter || (c.status || "a_tagger") === statusFilter));

  return (
    <div>
      <p className="radar-note">Clips partagés entre toutes les équipes du club — envoyés depuis Vidéothèque de chaque équipe, bouton "Envoyer vers la vidéothèque club". Assigne, suis le statut et laisse une note par clip si plusieurs personnes s'en partagent le travail.</p>

      <div className="roster-physical-grid" style={{ marginBottom: 14 }}>
        <label>Filtrer par assigné
          <select value={assigneeFilter} onChange={(e) => setAssigneeFilter(e.target.value)}>
            <option value="">Tout le monde</option>
            {staff.map((s) => <option key={s.id} value={s.id}>{s.firstName} {s.lastName}</option>)}
          </select>
        </label>
        <label>Filtrer par statut
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
            <option value="">Tous les statuts</option>
            {CLIP_STATUSES.map((s) => <option key={s.key} value={s.key}>{s.label}</option>)}
          </select>
        </label>
      </div>

      {filtered.length === 0 && <div className="empty-state">Aucun clip {assigneeFilter || statusFilter ? "ne correspond à ce filtre" : "partagé pour l'instant"}.</div>}
      <div className="clip-grid">
        {filtered.map((c) => {
          const assignedStaff = staff.find((s) => s.id === c.assignedTo);
          const status = c.status || "a_tagger";
          return (
            <div className="clip-card" key={c.id}>
              <video src={clipUrls[c.id]} controls />
              <div className="clip-card-info">
                <div className="clip-card-title">{c.player ? `n°${c.player}` : (c.club || (c.team === "us" ? "Équipe" : "Adversaire"))}</div>
                <div className="clip-card-meta">{c.matchName} · {teams.find((t) => t.id === c.sourceTeamId) ? teams.find((t) => t.id === c.sourceTeamId).name : "équipe inconnue"}</div>
                <div className="roster-physical-grid" style={{ marginTop: 6 }}>
                  <select value={c.assignedTo || ""} onChange={(e) => setAssignee(c.id, e.target.value)}>
                    <option value="">Non assigné</option>
                    {staff.map((s) => <option key={s.id} value={s.id}>{s.firstName} {s.lastName}</option>)}
                  </select>
                  <select value={status} onChange={(e) => setStatus(c.id, e.target.value)}>
                    {CLIP_STATUSES.map((s) => <option key={s.key} value={s.key}>{s.label}</option>)}
                  </select>
                </div>
                <input type="text" placeholder="Note (optionnel)" value={c.note || ""} onChange={(e) => setNote(c.id, e.target.value)} style={{ marginTop: 6, width: "100%", boxSizing: "border-box" }} />
                {assignedStaff && <div className="clip-card-meta" style={{ marginTop: 4 }}>Assigné à {assignedStaff.firstName} {assignedStaff.lastName}</div>}
              </div>
              <button className="icon-btn" style={{ position: "absolute", top: 8, right: 8 }} onClick={() => remove(c.id)} aria-label="Retirer">✕</button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

