function useCompetitionsList() {
  const [competitions, setCompetitions] = useState([]);
  useEffect(() => {
    try {
      const raw = localStorage.getItem("tf_competitions");
      setCompetitions(migrateCompetitionsData(raw ? JSON.parse(raw) : null).competitions);
    } catch (e) {
      setCompetitions([]);
    }
  }, []);
  return competitions;
}

