const MATCH_SHEET_ELEMENT_TYPES = [
  { key: "joueur", label: "Joueur", shape: "player", color: "#E3B23C" },
  { key: "adversaire", label: "Adversaire", shape: "disc", color: "#D6483F" },
  { key: "gardien", label: "Gardien", shape: "disc", color: "#5B8FD6" },
  { key: "ballon", label: "Ballon", shape: "ball", color: "#FFFFFF" },
  { key: "cone", label: "Plot", shape: "triangle", color: "#FF8C00" },
  { key: "but", label: "But", shape: "goalrect", color: "#FFFFFF" },
  { key: "zone", label: "Zone délimitée", shape: "zone", color: "#E3B23C" },
];

const matchSheetImageCache = {};
function getCachedPlayerImage(dataUrl, onLoad) {
  if (!dataUrl) return null;
  const cached = matchSheetImageCache[dataUrl];
  if (cached) return cached.complete ? cached : null;
  const img = new Image();
  img.onload = () => { if (onLoad) onLoad(); };
  img.onerror = () => {};
  img.src = dataUrl;
  matchSheetImageCache[dataUrl] = img;
  return null;
}

function drawMatchSheetElement(ctx, el, w, h, roster, onImageLoad) {
  if (el.type === "arrowMove" || el.type === "arrowPass" || el.type === "arrowDribble") {
    const x1 = el.x1 * w, y1 = el.y1 * h, x2 = el.x2 * w, y2 = el.y2 * h;
    const cx = el.cx != null ? el.cx * w : null, cy = el.cy != null ? el.cy * h : null;
    ctx.strokeStyle = el.color || "#E3B23C"; ctx.fillStyle = el.color || "#E3B23C"; ctx.lineWidth = 3;
    ctx.setLineDash(el.type === "arrowMove" ? [8, 6] : []);
    if (el.type === "arrowDribble") {
      drawWavyArrow(ctx, x1, y1, x2, y2, el.curved, cx, cy);
    } else if (el.curved && cx != null) {
      ctx.beginPath(); ctx.moveTo(x1, y1); ctx.quadraticCurveTo(cx, cy, x2, y2); ctx.stroke();
      drawArrowHeadOnly(ctx, cx, cy, x2, y2);
    } else {
      drawArrowHead(ctx, x1, y1, x2, y2);
    }
    ctx.setLineDash([]);
    return;
  }
  if (el.type === "zone") {
    const x1 = el.x1 * w, y1 = el.y1 * h, x2 = el.x2 * w, y2 = el.y2 * h;
    ctx.setLineDash([6, 4]); ctx.strokeStyle = el.color || "#E3B23C"; ctx.lineWidth = 2;
    ctx.strokeRect(Math.min(x1, x2), Math.min(y1, y2), Math.abs(x2 - x1), Math.abs(y2 - y1));
    ctx.setLineDash([]);
    return;
  }
  const x = el.x * w, y = el.y * h;
  ctx.save();
  if (el.rotation) { ctx.translate(x, y); ctx.rotate((el.rotation * Math.PI) / 180); ctx.translate(-x, -y); }
  if (el.type === "texte") {
    ctx.fillStyle = el.color || "#ffffff"; ctx.font = "bold 15px sans-serif";
    ctx.fillText(el.text || "", x, y);
    ctx.restore();
    return;
  }
  if (el.type === "joueur") {
    const player = (roster || []).find((p) => p.id === el.playerId);
    const radius = 16;
    const img = player && player.photo ? getCachedPlayerImage(player.photo, onImageLoad) : null;
    if (img) {
      ctx.save();
      ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI * 2); ctx.closePath(); ctx.clip();
      ctx.drawImage(img, x - radius, y - radius, radius * 2, radius * 2);
      ctx.restore();
      ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI * 2); ctx.strokeStyle = "#E3B23C"; ctx.lineWidth = 2; ctx.stroke();
    } else {
      ctx.fillStyle = "#E3B23C"; ctx.strokeStyle = "#1a1a1a"; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.arc(x, y, radius, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    }
    if (player) {
      const initials = playerFullName(player).split(" ").map((s) => s[0]).join("").slice(0, 2).toUpperCase();
      ctx.font = "bold 10px sans-serif"; ctx.textAlign = "center"; ctx.textBaseline = "top";
      ctx.fillStyle = "#EEF3EC";
      ctx.fillText(initials, x, y + radius + 3);
      ctx.textAlign = "left"; ctx.textBaseline = "alphabetic";
    }
    ctx.restore();
    return;
  }
  const def = MATCH_SHEET_ELEMENT_TYPES.find((t) => t.key === el.type);
  if (!def) { ctx.restore(); return; }
  ctx.fillStyle = def.color; ctx.strokeStyle = "#1a1a1a"; ctx.lineWidth = 1.5;
  if (def.shape === "disc") {
    ctx.beginPath(); ctx.arc(x, y, 11, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  } else if (def.shape === "triangle") {
    ctx.beginPath(); ctx.moveTo(x, y - 9); ctx.lineTo(x + 8, y + 7); ctx.lineTo(x - 8, y + 7); ctx.closePath(); ctx.fill(); ctx.stroke();
  } else if (def.shape === "ball") {
    ctx.beginPath(); ctx.arc(x, y, 7, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
  } else if (def.shape === "goalrect") {
    ctx.strokeRect(x - 12, y - 8, 24, 16);
  }
  ctx.restore();
}

function StaticSheetCanvas({ elements, roster, halfPitch }) {
  const wrapRef = useRef(null);
  const canvasRef = useRef(null);
  const [size, setSize] = useState({ w: 600, h: 400 });
  const [imgTick, setImgTick] = useState(0);

  useEffect(() => {
    function sync() { if (wrapRef.current) setSize({ w: wrapRef.current.clientWidth, h: wrapRef.current.clientHeight }); }
    sync();
    window.addEventListener("resize", sync);
    return () => window.removeEventListener("resize", sync);
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width = size.w; canvas.height = size.h;
    try {
      const ctx = canvas.getContext("2d");
      if (!ctx) return;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      (elements || []).forEach((el) => {
        try { drawMatchSheetElement(ctx, el, canvas.width, canvas.height, roster, () => setImgTick((t) => t + 1)); } catch (err) {}
      });
    } catch (err) {}
  }, [elements, size, roster, imgTick]);

  return (
    <div className="pad-wrap" ref={wrapRef}>
      {halfPitch ? <PitchBackgroundHalf /> : <PitchBackgroundFull />}
      <canvas ref={canvasRef} />
    </div>
  );
}

function PresentationWindow({ causerieId }) {
  const [causerie, setCauserie] = useState(null);
  const [roster, setRoster] = useState([]);
  const [sheetIndex, setSheetIndex] = useState(0);

  useEffect(() => {
    try {
      const all = JSON.parse(localStorage.getItem("tf_causeries") || "[]");
      setCauserie(all.find((c) => c.id === causerieId) || null);
    } catch (e) {}
    try { setRoster(JSON.parse(localStorage.getItem("tf_roster") || "[]")); } catch (e) {}

    const channel = new BroadcastChannel("tf_causerie_presentation");
    channel.onmessage = (e) => {
      if (e.data && e.data.type === "goto") setSheetIndex(e.data.index);
    };
    return () => channel.close();
  }, [causerieId]);

  if (!causerie) return <div style={{ background: "#0D1512", color: "#EEF3EC", height: "100vh", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18 }}>Chargement de la causerie…</div>;

  const sheet = causerie.sheets[sheetIndex];
  const selectedPlayers = roster.filter((p) => causerie.selectedPlayerIds.includes(p.id));

  return (
    <div style={{ background: "#0D1512", color: "#EEF3EC", height: "100vh", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", padding: 24 }}>
      {!sheet ? (
        <div style={{ fontSize: 22 }}>{causerie.name}{causerie.opponent && ` — vs ${causerie.opponent}`}</div>
      ) : (
        <>
          <div style={{ fontSize: 22, fontWeight: 700, marginBottom: 16, color: "#E3B23C" }}>{sheet.title}</div>
          <div style={{ width: "90%", maxWidth: 1000 }}>
            <StaticSheetCanvas elements={sheet.elements} roster={selectedPlayers} halfPitch={HALF_PITCH_SHEET_TITLES.includes(sheet.title)} />
          </div>
        </>
      )}
    </div>
  );
}

function MatchSheetEditor({ elements, setElements, roster, halfPitch }) {
  const wrapRef = useRef(null);
  const canvasRef = useRef(null);
  const [tool, setTool] = useState("joueur");
  const [pendingPoints, setPendingPoints] = useState([]);
  const [preview, setPreview] = useState(null);
  const [curveMode, setCurveMode] = useState(false);
  const [textPending, setTextPending] = useState(null);
  const [textValue, setTextValue] = useState("");
  const [playerPicker, setPlayerPicker] = useState(null);
  const [size, setSize] = useState({ w: 600, h: 400 });
  const [rotatingId, setRotatingId] = useState(null);
  const [imgTick, setImgTick] = useState(0);
  const isArrowTool = tool === "arrowMove" || tool === "arrowPass" || tool === "arrowDribble";
  const isZoneTool = tool === "zone";
  const isRotateTool = tool === "rotate";
  const isPlayerTool = tool === "joueur";
  const arrowColor = tool === "arrowMove" ? "#5B8FD6" : tool === "arrowDribble" ? "#B98FE0" : "#E3B23C";

  function syncSize() {
    if (wrapRef.current) setSize({ w: wrapRef.current.clientWidth, h: wrapRef.current.clientHeight });
  }
  useEffect(() => {
    syncSize();
    window.addEventListener("resize", syncSize);
    return () => window.removeEventListener("resize", syncSize);
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width = size.w;
    canvas.height = size.h;
  }, [size]);

  useEffect(() => { setPendingPoints([]); setPreview(null); setPlayerPicker(null); }, [tool]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    try {
      const ctx = canvas.getContext("2d");
      if (!ctx) return;
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      (elements || []).forEach((el) => {
        try { drawMatchSheetElement(ctx, el, canvas.width, canvas.height, roster, () => setImgTick((t) => t + 1)); } catch (err) { /* un élément corrompu ne doit pas bloquer les autres */ }
      });
      if (preview) {
        try { drawMatchSheetElement(ctx, preview, canvas.width, canvas.height, roster, null); } catch (err) {}
      }
      if (pendingPoints.length > 0) {
        ctx.fillStyle = isZoneTool ? "#E3B23C" : arrowColor;
        pendingPoints.forEach((p) => {
          ctx.beginPath(); ctx.arc(p.x * canvas.width, p.y * canvas.height, 5, 0, Math.PI * 2); ctx.fill();
        });
      }
    } catch (err) {
      console.error("Erreur de dessin sur la fiche", err);
    }
  }, [elements, preview, size, pendingPoints, isZoneTool, arrowColor, roster, imgTick]);

  function getPos(e) {
    if (!canvasRef.current) return { x: 0.5, y: 0.5 };
    const rect = canvasRef.current.getBoundingClientRect();
    if (!rect.width || !rect.height) return { x: 0.5, y: 0.5 };
    const touch = (e.touches && e.touches[0]) || (e.changedTouches && e.changedTouches[0]) || null;
    const clientX = touch ? touch.clientX : e.clientX;
    const clientY = touch ? touch.clientY : e.clientY;
    return { x: (clientX - rect.left) / rect.width, y: (clientY - rect.top) / rect.height };
  }

  function handleClick(e) {
    const pos = getPos(e);
    if (isRotateTool) return;
    if (tool === "texte") { setTextPending(pos); setTextValue(""); return; }
    if (isPlayerTool) { setPlayerPicker(pos); return; }

    if (isZoneTool) {
      if (pendingPoints.length === 0) { setPendingPoints([pos]); return; }
      setElements([...(elements || []), { id: newId(), type: "zone", x1: pendingPoints[0].x, y1: pendingPoints[0].y, x2: pos.x, y2: pos.y, color: "#E3B23C" }]);
      setPendingPoints([]); setPreview(null);
      return;
    }

    if (isArrowTool) {
      if (pendingPoints.length === 0) { setPendingPoints([pos]); return; }
      if (pendingPoints.length === 1) {
        if (!curveMode) {
          setElements([...(elements || []), { id: newId(), type: tool, x1: pendingPoints[0].x, y1: pendingPoints[0].y, x2: pos.x, y2: pos.y, curved: false, color: arrowColor }]);
          setPendingPoints([]); setPreview(null);
        } else {
          setPendingPoints([...pendingPoints, pos]);
        }
        return;
      }
      setElements([...(elements || []), { id: newId(), type: tool, x1: pendingPoints[0].x, y1: pendingPoints[0].y, x2: pendingPoints[1].x, y2: pendingPoints[1].y, curved: true, cx: pos.x, cy: pos.y, color: arrowColor }]);
      setPendingPoints([]); setPreview(null);
      return;
    }

    const def = MATCH_SHEET_ELEMENT_TYPES.find((t) => t.key === tool);
    setElements([...(elements || []), { id: newId(), type: tool, x: pos.x, y: pos.y, color: def ? def.color : "#fff" }]);
  }

  function placePlayer(playerId) {
    if (!playerPicker) return;
    setElements([...(elements || []), { id: newId(), type: "joueur", x: playerPicker.x, y: playerPicker.y, playerId }]);
    setPlayerPicker(null);
  }

  function handleMouseDown(e) {
    if (!isRotateTool) return;
    const pos = getPos(e);
    const target = findNearestRotatable(pos, elements || []);
    if (target) setRotatingId(target.id);
  }

  function rotationCenter(el) {
    if (el.type === "zone") return { cx: (el.x1 + el.x2) / 2, cy: (el.y1 + el.y2) / 2 };
    if (el.x != null && el.y != null) return { cx: el.x, cy: el.y };
    return { cx: 0.5, cy: 0.5 };
  }

  function handleMove(e) {
    const pos = getPos(e);
    if (isRotateTool && rotatingId) {
      const el = (elements || []).find((x) => x.id === rotatingId);
      if (!el) return;
      const { cx, cy } = rotationCenter(el);
      const angle = (Math.atan2(pos.y - cy, pos.x - cx) * 180) / Math.PI;
      setElements((elements || []).map((x) => (x.id === rotatingId ? { ...x, rotation: (angle + 360) % 360 } : x)));
      return;
    }
    if (pendingPoints.length === 0) return;
    if (isZoneTool) {
      setPreview({ type: "zone", x1: pendingPoints[0].x, y1: pendingPoints[0].y, x2: pos.x, y2: pos.y, color: "#E3B23C" });
      return;
    }
    if (isArrowTool) {
      if (pendingPoints.length === 1) {
        setPreview({ type: tool, x1: pendingPoints[0].x, y1: pendingPoints[0].y, x2: pos.x, y2: pos.y, curved: false, color: arrowColor });
      } else {
        setPreview({ type: tool, x1: pendingPoints[0].x, y1: pendingPoints[0].y, x2: pendingPoints[1].x, y2: pendingPoints[1].y, curved: true, cx: pos.x, cy: pos.y, color: arrowColor });
      }
    }
  }

  function handleMouseUp() {
    setRotatingId(null);
  }

  // Support tactile : mêmes gestionnaires que la souris, avec preventDefault pour éviter le
  // scroll/zoom du navigateur pendant le dessin et empêcher les événements souris de synthèse
  // que certains navigateurs déclenchent après un touchend.
  function handleTouchStart(e) { e.preventDefault(); handleMouseDown(e); }
  function handleTouchMove(e) { e.preventDefault(); handleMove(e); }
  function handleTouchEnd(e) { e.preventDefault(); handleMouseUp(); handleClick(e); }

  function commitText() {
    if (textValue.trim() && textPending) setElements([...(elements || []), { id: newId(), type: "texte", x: textPending.x, y: textPending.y, text: textValue.trim(), color: "#ffffff" }]);
    setTextPending(null);
  }
  function undoLast() { setElements((elements || []).slice(0, -1)); }
  function clearAll() { if (confirm("Effacer tout le schéma ?")) setElements([]); }

  let stepHint = "";
  if (isZoneTool) stepHint = pendingPoints.length === 0 ? "Clique un premier coin de la zone." : "Clique le coin opposé pour fixer la taille.";
  else if (isArrowTool) {
    if (pendingPoints.length === 0) stepHint = "Clique le point de départ de la flèche.";
    else if (pendingPoints.length === 1) stepHint = curveMode ? "Clique le point d'arrivée." : "Clique le point d'arrivée pour valider.";
    else stepHint = "Clique pour définir la courbure.";
  } else if (isRotateTool) {
    stepHint = "Clique un élément et fais glisser la souris autour de lui pour l'orienter.";
  }

  return (
    <div>
      <div className="clip-editor-toolbar pad-toolbar">
        {MATCH_SHEET_ELEMENT_TYPES.map((t) => (
          <button key={t.key} className={`qcm-option ${tool === t.key ? "selected" : ""}`} onClick={() => setTool(t.key)}>{t.label}</button>
        ))}
        <button className={`qcm-option ${tool === "arrowMove" ? "selected" : ""}`} onClick={() => setTool("arrowMove")}>Flèche course</button>
        <button className={`qcm-option ${tool === "arrowPass" ? "selected" : ""}`} onClick={() => setTool("arrowPass")}>Flèche passe</button>
        <button className={`qcm-option ${tool === "arrowDribble" ? "selected" : ""}`} onClick={() => setTool("arrowDribble")}>Flèche course + ballon</button>
        <button className={`qcm-option ${tool === "texte" ? "selected" : ""}`} onClick={() => setTool("texte")}>Texte</button>
        <button className={`qcm-option ${isRotateTool ? "selected" : ""}`} onClick={() => setTool("rotate")}>Pivoter</button>
        {isArrowTool && (
          <label className="pad-curve-toggle">
            <input type="checkbox" checked={curveMode} onChange={(e) => setCurveMode(e.target.checked)} /> Courber
          </label>
        )}
        <button className="btn btn-ghost btn-small" onClick={undoLast} disabled={(elements || []).length === 0}>Annuler le dernier</button>
        <button className="btn btn-ghost btn-small" onClick={clearAll} disabled={(elements || []).length === 0}>Tout effacer</button>
      </div>
      {stepHint && <p className="hint" style={{ marginTop: 0, marginBottom: 8 }}>{stepHint}</p>}
      {isPlayerTool && !playerPicker && <p className="hint" style={{ marginTop: 0, marginBottom: 8 }}>Clique sur le terrain pour choisir quel joueur y placer.</p>}
      <div className={`pad-wrap ${halfPitch ? "pad-wrap-half" : ""}`} ref={wrapRef}>
        {halfPitch ? <PitchBackgroundHalf /> : <PitchBackgroundFull />}
        <canvas ref={canvasRef} onClick={handleClick} onMouseDown={handleMouseDown} onMouseMove={handleMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp} onTouchStart={handleTouchStart} onTouchMove={handleTouchMove} onTouchEnd={handleTouchEnd} style={{ cursor: isRotateTool ? "grab" : undefined, touchAction: "none" }} />
        {textPending && (
          <div className="clip-text-popup" style={{ left: textPending.x * size.w, top: textPending.y * size.h }}>
            <input autoFocus type="text" placeholder="Texte…" value={textValue} onChange={(e) => setTextValue(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") commitText(); if (e.key === "Escape") setTextPending(null); }} />
            <button className="btn btn-primary btn-small" onClick={commitText}>Ajouter</button>
          </div>
        )}
        {playerPicker && (
          <div className="clip-text-popup player-picker-popup" style={{ left: playerPicker.x * size.w, top: playerPicker.y * size.h }}>
            {(roster || []).length === 0 && <span className="hint" style={{ margin: 0 }}>Aucun joueur retenu pour cette causerie.</span>}
            {(roster || []).map((p) => (
              <button key={p.id} className="player-picker-item" onClick={() => placePlayer(p.id)}>
                {p.photo ? <img src={p.photo} alt="" /> : <span className="player-picker-noimg">{playerFullName(p).slice(0, 2).toUpperCase()}</span>}
                {playerFullName(p)}
              </button>
            ))}
            <button className="btn btn-ghost btn-small" onClick={() => setPlayerPicker(null)}>Annuler</button>
          </div>
        )}
      </div>
      <p className="hint">Choisis un élément puis clique sur le terrain. Pour "Joueur", choisis ensuite qui placer dans la liste — sa photo s'affiche si elle est renseignée dans Effectifs. Flèches et zone se placent en plusieurs clics ; "Pivoter" oriente un élément déjà placé au clic-glisse.</p>
    </div>
  );
}



function TacticalPadEditor({ elements, setElements, nextFrameElements, frameKey }) {
  const wrapRef = useRef(null);
  const canvasRef = useRef(null);
  const [tool, setTool] = useState("playerA");
  const [pendingPoints, setPendingPoints] = useState([]);
  const [preview, setPreview] = useState(null);
  const [curveMode, setCurveMode] = useState(false);
  const [textPending, setTextPending] = useState(null);
  const [textValue, setTextValue] = useState("");
  const [size, setSize] = useState({ w: 600, h: 400 });
  const [rotatingId, setRotatingId] = useState(null);
  const [movingId, setMovingId] = useState(null);
  const [moveDragStart, setMoveDragStart] = useState(null);
  const [moveDragOrigin, setMoveDragOrigin] = useState(null);
  const [color, setColor] = useState("#E3B23C");
  const [curvingId, setCurvingId] = useState(null);
  const [curveMousePos, setCurveMousePos] = useState(null);
  const [waypointingId, setWaypointingId] = useState(null);
  const [pathPoints, setPathPoints] = useState([]);
  const [waypointMousePos, setWaypointMousePos] = useState(null);
  const isArrowTool = tool === "arrowMove" || tool === "arrowPass" || tool === "arrowDribble";
  const isZoneTool = tool === "zone";
  const isRotateTool = tool === "rotate";
  const isMoveTool = tool === "move";
  const isRecolorTool = tool === "recolor";
  const isDeleteTool = tool === "delete";
  const isCurveTool = tool === "curveMove";
  const isWaypointTool = tool === "waypoints";

  // La couleur proposée repart sur une valeur par défaut sensée à chaque changement d'outil
  // (celle du type, ou la convention déjà en place pour les flèches/zone/texte), mais reste
  // modifiable via le sélecteur juste avant de placer ou de recolorer un élément.
  useEffect(() => {
    if (tool === "arrowMove") setColor("#5B8FD6");
    else if (tool === "arrowPass") setColor("#E3B23C");
    else if (tool === "arrowDribble") setColor("#B98FE0");
    else if (tool === "zone") setColor("#E3B23C");
    else if (tool === "text") setColor("#ffffff");
    else {
      const def = PAD_ELEMENT_TYPES.find((t) => t.key === tool);
      if (def) setColor(def.color);
    }
  }, [tool]);

  function syncSize() {
    if (wrapRef.current) setSize({ w: wrapRef.current.clientWidth, h: wrapRef.current.clientHeight });
  }
  useEffect(() => {
    syncSize();
    window.addEventListener("resize", syncSize);
    return () => window.removeEventListener("resize", syncSize);
  }, []);

  // Le redimensionnement du canvas ne dépend QUE de sa taille réelle — jamais du dessin en cours,
  // pour éviter de perturber la détection des clics pendant une interaction à plusieurs étapes.
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    canvas.width = size.w;
    canvas.height = size.h;
  }, [size]);

  useEffect(() => {
    setPendingPoints([]); setPreview(null);
    setWaypointingId(null); setPathPoints([]); setWaypointMousePos(null);
  }, [tool]);

  // Changer d'image (onglet "Image N") réutilise ce même éditeur monté une seule fois — sans ça,
  // une interaction en cours sur une image (ex. courbure ou trajet à mi-chemin) pourrait s'appliquer
  // par erreur à l'image suivante après un changement d'onglet.
  useEffect(() => {
    setCurvingId(null); setCurveMousePos(null);
    setPendingPoints([]); setPreview(null);
    setRotatingId(null); setMovingId(null); setMoveDragStart(null); setMoveDragOrigin(null);
    setWaypointingId(null); setPathPoints([]); setWaypointMousePos(null);
  }, [frameKey]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Image suivante en filigrane : juste un repère pour placer/courber un déplacement, jamais
    // affiché pendant la lecture (voir ExerciseAnimationPlayer).
    if (nextFrameElements) {
      ctx.save();
      ctx.globalAlpha = 0.25;
      nextFrameElements.forEach((el) => drawPadElement(ctx, el, canvas.width, canvas.height));
      ctx.restore();
    }

    // Trajets déjà définis vers l'image suivante (points de passage + courbure finale), en aperçu
    // permanent tant qu'on ne les modifie pas — l'élément en cours d'édition est géré plus bas.
    if (nextFrameElements) {
      elements.forEach((el) => {
        if (el.id === waypointingId || el.x == null) return;
        const hasPath = (el.movePath && el.movePath.length > 0) || el.moveCx != null;
        if (!hasPath) return;
        const target = nextFrameElements.find((e) => e.id === el.id);
        if (!target) return;
        let px = el.x, py = el.y;
        (el.movePath || []).forEach((p) => {
          drawPathIndicator(ctx, px, py, p.cx, p.cy, p.x, p.y, el.color || "#ffffff", canvas.width, canvas.height);
          px = p.x; py = p.y;
        });
        drawPathIndicator(ctx, px, py, el.moveCx, el.moveCy, target.x, target.y, el.color || "#ffffff", canvas.width, canvas.height);
      });
    }

    elements.forEach((el) => drawPadElement(ctx, el, canvas.width, canvas.height));
    if (preview) drawPadElement(ctx, preview, canvas.width, canvas.height);

    // Aperçu en direct du point de courbure (outil "Courber un trajet").
    if (isCurveTool && curvingId != null && curveMousePos && nextFrameElements) {
      const src = elements.find((x) => x.id === curvingId);
      const target = nextFrameElements.find((x) => x.id === curvingId);
      if (src && target) drawPathIndicator(ctx, src.x, src.y, curveMousePos.x, curveMousePos.y, target.x, target.y, color, canvas.width, canvas.height);
    }

    // Aperçu en direct du trajet à points de passage en cours de construction.
    if (isWaypointTool && waypointingId != null && nextFrameElements) {
      const src = elements.find((x) => x.id === waypointingId);
      if (src) {
        let px = src.x, py = src.y;
        pathPoints.forEach((p) => {
          drawPathIndicator(ctx, px, py, p.cx, p.cy, p.x, p.y, color, canvas.width, canvas.height);
          ctx.save(); ctx.fillStyle = color; ctx.beginPath(); ctx.arc(p.x * canvas.width, p.y * canvas.height, 4, 0, Math.PI * 2); ctx.fill(); ctx.restore();
          px = p.x; py = p.y;
        });
        if (waypointMousePos) {
          if (curveMode && pendingPoints.length === 1) {
            drawPathIndicator(ctx, px, py, pendingPoints[0].x, pendingPoints[0].y, waypointMousePos.x, waypointMousePos.y, color, canvas.width, canvas.height);
          } else if (!curveMode) {
            drawPathIndicator(ctx, px, py, null, null, waypointMousePos.x, waypointMousePos.y, color, canvas.width, canvas.height);
          }
        }
      }
    }

    if (pendingPoints.length > 0) {
      ctx.fillStyle = color;
      pendingPoints.forEach((p) => {
        ctx.beginPath(); ctx.arc(p.x * canvas.width, p.y * canvas.height, 5, 0, Math.PI * 2); ctx.fill();
      });
    }
  }, [elements, preview, size, pendingPoints, color, nextFrameElements, isCurveTool, curvingId, curveMousePos, isWaypointTool, waypointingId, pathPoints, waypointMousePos, curveMode]);

  function getPos(e) {
    const rect = canvasRef.current.getBoundingClientRect();
    const touch = (e.touches && e.touches[0]) || (e.changedTouches && e.changedTouches[0]) || null;
    const clientX = touch ? touch.clientX : e.clientX;
    const clientY = touch ? touch.clientY : e.clientY;
    return { x: (clientX - rect.left) / rect.width, y: (clientY - rect.top) / rect.height };
  }

  function handleClick(e) {
    const pos = getPos(e);
    if (isRotateTool || isMoveTool) return; // gérés au clic-glisse (mousedown/mousemove/mouseup)
    if (tool === "text") { setTextPending(pos); setTextValue(""); return; }

    if (isCurveTool) {
      if (!nextFrameElements) return; // pas d'image suivante -> rien à courber
      if (curvingId == null) {
        const target = findNearestElement(pos, elements);
        if (!target || target.x == null) return; // limité aux éléments ponctuels
        if (!nextFrameElements.some((e) => e.id === target.id)) return; // ne bouge pas vers l'image suivante
        if (target.moveCx != null) {
          // déjà courbé -> reclique dessus pour repasser en ligne droite
          setElements((prev) => prev.map((x) => (x.id === target.id ? { ...x, moveCx: undefined, moveCy: undefined } : x)));
          return;
        }
        setCurvingId(target.id);
        setCurveMousePos(pos);
        return;
      }
      setElements((prev) => prev.map((x) => (x.id === curvingId ? { ...x, moveCx: pos.x, moveCy: pos.y } : x)));
      setCurvingId(null);
      setCurveMousePos(null);
      return;
    }

    if (isWaypointTool) {
      if (!nextFrameElements) return; // pas d'image suivante -> rien à jalonner
      if (waypointingId == null) {
        const target = findNearestElement(pos, elements);
        if (!target || target.x == null) return; // limité aux éléments ponctuels
        if (!nextFrameElements.some((e) => e.id === target.id)) return; // ne bouge pas vers l'image suivante
        setWaypointingId(target.id);
        setPathPoints((target.movePath || []).map((p) => ({ ...p }))); // reprend le trajet existant pour le compléter
        setPendingPoints([]);
        return;
      }
      if (!curveMode) {
        setPathPoints((prev) => [...prev, { x: pos.x, y: pos.y }]);
        return;
      }
      if (pendingPoints.length === 0) { setPendingPoints([pos]); return; } // 1er clic = point de courbure du prochain segment
      setPathPoints((prev) => [...prev, { x: pos.x, y: pos.y, cx: pendingPoints[0].x, cy: pendingPoints[0].y }]);
      setPendingPoints([]);
      return;
    }

    if (isRecolorTool) {
      const target = findNearestElement(pos, elements);
      if (target) setElements((prev) => prev.map((x) => (x.id === target.id ? { ...x, color } : x)));
      return;
    }
    if (isDeleteTool) {
      const target = findNearestElement(pos, elements);
      if (target) setElements((prev) => prev.filter((x) => x.id !== target.id));
      return;
    }

    if (isZoneTool) {
      if (pendingPoints.length === 0) { setPendingPoints([pos]); return; }
      setElements((prev) => [...prev, { id: newId(), type: "zone", x1: pendingPoints[0].x, y1: pendingPoints[0].y, x2: pos.x, y2: pos.y, color }]);
      setPendingPoints([]); setPreview(null);
      return;
    }

    if (isArrowTool) {
      if (pendingPoints.length === 0) { setPendingPoints([pos]); return; }
      if (pendingPoints.length === 1) {
        if (!curveMode) {
          setElements((prev) => [...prev, { id: newId(), type: tool, x1: pendingPoints[0].x, y1: pendingPoints[0].y, x2: pos.x, y2: pos.y, curved: false, color }]);
          setPendingPoints([]); setPreview(null);
        } else {
          setPendingPoints([...pendingPoints, pos]);
        }
        return;
      }
      // 3e clic : point de courbure
      setElements((prev) => [...prev, { id: newId(), type: tool, x1: pendingPoints[0].x, y1: pendingPoints[0].y, x2: pendingPoints[1].x, y2: pendingPoints[1].y, curved: true, cx: pos.x, cy: pos.y, color }]);
      setPendingPoints([]); setPreview(null);
      return;
    }

    setElements((prev) => [...prev, { id: newId(), type: tool, x: pos.x, y: pos.y, color }]);
  }

  function handleMouseDown(e) {
    const pos = getPos(e);
    if (isRotateTool) {
      const target = findNearestRotatable(pos, elements);
      if (target) setRotatingId(target.id);
      return;
    }
    if (isMoveTool) {
      const target = findNearestElement(pos, elements);
      if (!target) return;
      setMovingId(target.id);
      setMoveDragStart(pos);
      setMoveDragOrigin(
        target.x1 != null
          ? { x1: target.x1, y1: target.y1, x2: target.x2, y2: target.y2, cx: target.cx, cy: target.cy }
          : { x: target.x, y: target.y }
      );
    }
  }

  function rotationCenter(el) {
    if (el.type === "zone") return { cx: (el.x1 + el.x2) / 2, cy: (el.y1 + el.y2) / 2 };
    return { cx: el.x, cy: el.y };
  }

  function handleMove(e) {
    const pos = getPos(e);
    if (isCurveTool && curvingId != null) { setCurveMousePos(pos); return; }
    if (isWaypointTool && waypointingId != null) { setWaypointMousePos(pos); return; }
    if (isRotateTool && rotatingId) {
      const el = elements.find((x) => x.id === rotatingId);
      if (!el) return;
      const { cx, cy } = rotationCenter(el);
      const angle = (Math.atan2(pos.y - cy, pos.x - cx) * 180) / Math.PI;
      setElements((prev) => prev.map((x) => (x.id === rotatingId ? { ...x, rotation: (angle + 360) % 360 } : x)));
      return;
    }
    if (isMoveTool && movingId && moveDragStart && moveDragOrigin) {
      const dx = pos.x - moveDragStart.x, dy = pos.y - moveDragStart.y;
      setElements((prev) => prev.map((x) => {
        if (x.id !== movingId) return x;
        if (moveDragOrigin.x1 != null) {
          const next = { ...x, x1: moveDragOrigin.x1 + dx, y1: moveDragOrigin.y1 + dy, x2: moveDragOrigin.x2 + dx, y2: moveDragOrigin.y2 + dy };
          if (moveDragOrigin.cx != null) { next.cx = moveDragOrigin.cx + dx; next.cy = moveDragOrigin.cy + dy; }
          return next;
        }
        return { ...x, x: moveDragOrigin.x + dx, y: moveDragOrigin.y + dy };
      }));
      return;
    }
    if (pendingPoints.length === 0) return;
    if (isZoneTool) {
      setPreview({ type: "zone", x1: pendingPoints[0].x, y1: pendingPoints[0].y, x2: pos.x, y2: pos.y, color });
      return;
    }
    if (isArrowTool) {
      if (pendingPoints.length === 1) {
        setPreview({ type: tool, x1: pendingPoints[0].x, y1: pendingPoints[0].y, x2: pos.x, y2: pos.y, curved: false, color });
      } else {
        setPreview({ type: tool, x1: pendingPoints[0].x, y1: pendingPoints[0].y, x2: pendingPoints[1].x, y2: pendingPoints[1].y, curved: true, cx: pos.x, cy: pos.y, color });
      }
    }
  }

  function handleMouseUp() {
    setRotatingId(null);
    setMovingId(null);
    setMoveDragStart(null);
    setMoveDragOrigin(null);
  }

  // Support tactile : mêmes gestionnaires que la souris (getPos gère déjà les deux types
  // d'événement), avec preventDefault pour éviter le scroll/zoom du navigateur pendant le dessin
  // et empêcher les événements souris de synthèse que certains navigateurs déclenchent après un
  // touchend (qui déclencheraient sinon l'action une seconde fois).
  function handleTouchStart(e) { e.preventDefault(); handleMouseDown(e); }
  function handleTouchMove(e) { e.preventDefault(); handleMove(e); }
  function handleTouchEnd(e) { e.preventDefault(); handleMouseUp(); handleClick(e); }

  function commitText() {
    if (textValue.trim()) setElements((prev) => [...prev, { id: newId(), type: "text", x: textPending.x, y: textPending.y, text: textValue.trim(), color }]);
    setTextPending(null);
  }
  function undoLast() { setElements((prev) => prev.slice(0, -1)); }
  function clearAll() { if (confirm("Effacer tout le schéma ?")) setElements([]); }
  function finishWaypoints() {
    setElements((prev) => prev.map((x) => (x.id === waypointingId ? { ...x, movePath: pathPoints } : x)));
    setWaypointingId(null); setPathPoints([]); setPendingPoints([]);
  }
  function cancelWaypoints() { setWaypointingId(null); setPathPoints([]); setPendingPoints([]); }
  function undoLastWaypoint() { setPathPoints((prev) => prev.slice(0, -1)); }

  let stepHint = "";
  if (isZoneTool) stepHint = pendingPoints.length === 0 ? "Clique un premier coin de la zone." : "Clique le coin opposé pour fixer la taille.";
  else if (isArrowTool) {
    if (pendingPoints.length === 0) stepHint = "Clique le point de départ de la flèche.";
    else if (pendingPoints.length === 1) stepHint = curveMode ? "Clique le point d'arrivée." : "Clique le point d'arrivée pour valider.";
    else stepHint = "Clique pour définir la courbure.";
  } else if (isMoveTool) stepHint = "Clique un élément et fais-le glisser vers sa nouvelle position.";
  else if (isRecolorTool) stepHint = "Clique un élément pour lui appliquer la couleur sélectionnée à droite.";
  else if (isDeleteTool) stepHint = "Clique un élément pour le supprimer.";
  else if (isCurveTool) {
    if (!nextFrameElements) stepHint = "Ajoute une image suivante pour pouvoir courber un déplacement vers elle.";
    else if (curvingId == null) stepHint = "Clique un élément qui bouge vers l'image suivante (visible en filigrane) — ça courbe son dernier segment, après ses éventuels points de passage. Reclique un élément déjà courbé pour repasser ce segment en ligne droite.";
    else stepHint = "Clique où le trajet doit passer pour définir la courbe.";
  } else if (isWaypointTool) {
    if (!nextFrameElements) stepHint = "Ajoute une image suivante pour pouvoir définir des points de passage.";
    else if (waypointingId == null) stepHint = "Clique un élément qui bouge vers l'image suivante pour construire son trajet en plusieurs étapes.";
    else if (curveMode && pendingPoints.length === 0) stepHint = "Clique où ce segment doit courber, puis clique le point de passage à atteindre.";
    else if (curveMode && pendingPoints.length === 1) stepHint = "Clique le point de passage à atteindre.";
    else stepHint = `Clique chaque point de passage successif (${pathPoints.length} pour l'instant), puis "Terminer ce trajet".`;
  }

  return (
    <div>
      <div className="clip-editor-toolbar pad-toolbar">
        {PAD_ELEMENT_TYPES.map((t) => (
          <button key={t.key} className={`qcm-option ${tool === t.key ? "selected" : ""}`} onClick={() => setTool(t.key)}>{t.label}</button>
        ))}
        <button className={`qcm-option ${tool === "arrowMove" ? "selected" : ""}`} onClick={() => setTool("arrowMove")}>Flèche course</button>
        <button className={`qcm-option ${tool === "arrowPass" ? "selected" : ""}`} onClick={() => setTool("arrowPass")}>Flèche passe</button>
        <button className={`qcm-option ${tool === "arrowDribble" ? "selected" : ""}`} onClick={() => setTool("arrowDribble")}>Flèche course + ballon</button>
        <button className={`qcm-option ${tool === "text" ? "selected" : ""}`} onClick={() => setTool("text")}>Texte</button>
        <button className={`qcm-option ${isRotateTool ? "selected" : ""}`} onClick={() => setTool("rotate")}>Pivoter</button>
        <button className={`qcm-option ${isMoveTool ? "selected" : ""}`} onClick={() => setTool("move")}>Déplacer</button>
        <button className={`qcm-option ${isWaypointTool ? "selected" : ""}`} onClick={() => setTool("waypoints")} disabled={!nextFrameElements}>Points de passage</button>
        <button className={`qcm-option ${isCurveTool ? "selected" : ""}`} onClick={() => setTool("curveMove")} disabled={!nextFrameElements}>Courber un trajet</button>
        <button className={`qcm-option ${isRecolorTool ? "selected" : ""}`} onClick={() => setTool("recolor")}>Recolorer</button>
        <button className={`qcm-option ${isDeleteTool ? "selected" : ""}`} onClick={() => setTool("delete")}>Supprimer un élément</button>
        <label className="pad-curve-toggle" style={{ display: "flex", alignItems: "center", gap: 6 }}>
          Couleur
          <input type="color" value={color} onChange={(e) => setColor(e.target.value)} style={{ width: 30, height: 24, padding: 0, border: "none", background: "none", cursor: "pointer" }} />
        </label>
        {(isArrowTool || isWaypointTool) && (
          <label className="pad-curve-toggle">
            <input type="checkbox" checked={curveMode} onChange={(e) => setCurveMode(e.target.checked)} /> Courber
          </label>
        )}
        <button className="btn btn-ghost btn-small" onClick={undoLast} disabled={elements.length === 0}>Annuler le dernier</button>
        <button className="btn btn-ghost btn-small" onClick={clearAll} disabled={elements.length === 0}>Tout effacer</button>
      </div>
      {isWaypointTool && waypointingId != null && (
        <div className="clip-editor-toolbar pad-toolbar" style={{ marginTop: -4, marginBottom: 8 }}>
          <button className="btn btn-primary btn-small" onClick={finishWaypoints}>Terminer ce trajet ({pathPoints.length} point{pathPoints.length !== 1 ? "s" : ""})</button>
          <button className="btn btn-ghost btn-small" onClick={undoLastWaypoint} disabled={pathPoints.length === 0}>Annuler le dernier point</button>
          <button className="btn btn-ghost btn-small" onClick={cancelWaypoints}>Annuler ce trajet</button>
        </div>
      )}
      {isRotateTool && <p className="hint" style={{ marginTop: 0, marginBottom: 8 }}>Clique un élément et fais glisser la souris autour de lui pour l'orienter.</p>}
      {stepHint && <p className="hint" style={{ marginTop: 0, marginBottom: 8 }}>{stepHint}</p>}
      <div className="pad-wrap" ref={wrapRef}>
        <PitchBackgroundFull />
        <canvas ref={canvasRef} onClick={handleClick} onMouseDown={handleMouseDown} onMouseMove={handleMove} onMouseUp={handleMouseUp} onMouseLeave={handleMouseUp} onTouchStart={handleTouchStart} onTouchMove={handleTouchMove} onTouchEnd={handleTouchEnd} style={{ cursor: isRotateTool || isMoveTool ? "grab" : (isDeleteTool || isRecolorTool || isCurveTool || isWaypointTool ? "pointer" : undefined), touchAction: "none" }} />
        {textPending && (
          <div className="clip-text-popup" style={{ left: textPending.x * size.w, top: textPending.y * size.h }}>
            <input autoFocus type="text" placeholder="Texte…" value={textValue} onChange={(e) => setTextValue(e.target.value)}
              onKeyDown={(e) => { if (e.key === "Enter") commitText(); if (e.key === "Escape") setTextPending(null); }} />
            <button className="btn btn-primary btn-small" onClick={commitText}>Ajouter</button>
          </div>
        )}
      </div>
      <p className="hint">Choisis un élément et une couleur puis clique sur le terrain pour le placer. Pour les flèches et la zone, un clic par étape (coche "Courber" avant de commencer pour ajouter un point de courbure). "Flèche course" est en pointillés, "Flèche passe" en trait plein, "Flèche course + ballon" est ondulée. "Pivoter" oriente un élément au clic-glisse, "Déplacer" le repositionne au clic-glisse. "Points de passage" construit un trajet en plusieurs étapes (un clic par point, coche "Courber" pour incurver un segment avant de placer son point d'arrivée) ; "Courber un trajet" incurve seulement le tout dernier segment, sans étape intermédiaire. "Recolorer" et "Supprimer un élément" agissent au clic simple.</p>
    </div>
  );
}

export function emptyExerciseForm() {
  return { name: "", objectif: "", duree: 15, nbJoueurs: "", materiel: "", description: "", gameplanSection: "", gameplanChoice: "", gameplanLinks: [], diagram: [], diagramFrames: [], category: "tactique", theme: "", ageFormat: "standard", fffBracket: "", fffCategory: "", curriculumFederation: "" };
}
// La séquence complète d'un exercice = son image de base (diagram, inchangée pour compat avec
// les 478 exercices existants) + ses images suivantes (diagramFrames), s'il y en a. Un exercice
// sans diagramFrames renvoie une séquence à une seule image : comportement strictement identique
// à avant l'ajout de l'animation.
export function getExerciseFrames(ex) {
  return [ex && ex.diagram ? ex.diagram : [], ...((ex && ex.diagramFrames) || [])];
}
