function emptyProgramForm() {
  return { name: "", injuryCategory: "Musculaire", notes: "", phases: [] };
}
function emptyPhase() {
  return { id: newId(), name: "", dureeJours: 3, objectifs: "", exercices: "" };
}

function ProgramsScreen({ programs, setPrograms }) {
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyProgramForm());

  function openNew() { setForm(emptyProgramForm()); setEditingId(null); setShowForm(true); }
  function openEdit(p) { setForm({ ...emptyProgramForm(), ...p }); setEditingId(p.id); setShowForm(true); }
  function addPhase() { setForm((f) => ({ ...f, phases: [...f.phases, emptyPhase()] })); }
  function updatePhase(idx, field, value) {
    setForm((f) => ({ ...f, phases: f.phases.map((ph, i) => (i === idx ? { ...ph, [field]: value } : ph)) }));
  }
  function removePhase(idx) {
    setForm((f) => ({ ...f, phases: f.phases.filter((_, i) => i !== idx) }));
  }
  function save() {
    if (!form.name.trim()) { alert("Le nom du programme est obligatoire."); return; }
    if (editingId) setPrograms((prev) => prev.map((p) => (p.id === editingId ? { ...p, ...form } : p)));
    else setPrograms((prev) => [...prev, { id: newId(), ...form }]);
    setShowForm(false);
  }
  function remove(id) {
    if (!confirm("Supprimer ce modèle de programme ?")) return;
    setPrograms((prev) => prev.filter((p) => p.id !== id));
  }
  function importProgramsFile(file) {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const parsed = JSON.parse(e.target.result);
        const list = Array.isArray(parsed) ? parsed : [parsed];
        setPrograms((prev) => {
          const merged = [...prev];
          list.forEach((p) => {
            const entry = { ...emptyProgramForm(), ...p, id: p.id || newId(), phases: (p.phases || []).map((ph) => ({ ...emptyPhase(), ...ph })) };
            const idx = merged.findIndex((m) => m.id === entry.id);
            if (idx >= 0) merged[idx] = entry; else merged.push(entry);
          });
          return merged;
        });
        alert(`${list.length} programme${list.length > 1 ? "s" : ""} importé${list.length > 1 ? "s" : ""}.`);
      } catch (err) {
        alert("Le fichier n'a pas pu être importé (JSON invalide).");
      }
    };
    reader.readAsText(file);
  }

  function populateStarterPrograms() {
    const existingNames = new Set(programs.map((p) => p.name));
    const toAdd = STARTER_PROGRAMS.filter((p) => !existingNames.has(p.name)).map((p) => ({ id: newId(), ...emptyProgramForm(), ...p, phases: p.phases.map((ph) => ({ ...emptyPhase(), ...ph, id: newId() })) }));
    if (toAdd.length === 0) { alert("Les modèles de démarrage sont déjà présents."); return; }
    setPrograms((prev) => [...prev, ...toAdd]);
    alert(`${toAdd.length} modèle${toAdd.length > 1 ? "s" : ""} de programme ajouté${toAdd.length > 1 ? "s" : ""} pour les blessures les plus courantes — à faire valider et ajuster par ton kiné/médecin avant application réelle, ce sont des structures de départ.`);
  }

  const grouped = {};
  INJURY_CATEGORIES.forEach((c) => { grouped[c] = programs.filter((p) => p.injuryCategory === c); });

  return (
    <div>
      <p className="radar-note">Des modèles génériques par catégorie de blessure — chacun se personnalise ensuite au profil du joueur au moment où il est appliqué à une blessure précise, sans modifier le modèle d'origine.</p>
      {!showForm && (
        <div className="home-actions-row" style={{ marginBottom: 20 }}>
          <button className="btn btn-primary btn-large" onClick={openNew}>+ Créer un programme</button>
          <button className="btn btn-ghost btn-large" onClick={() => document.getElementById("programs-import-input").click()}>Importer un/des programme(s) JSON</button>
          <button className="btn btn-ghost btn-large" onClick={populateStarterPrograms}>Pré-remplir avec des modèles courants</button>
          <input id="programs-import-input" type="file" accept="application/json" style={{ display: "none" }} onChange={(e) => { if (e.target.files && e.target.files[0]) importProgramsFile(e.target.files[0]); e.target.value = ""; }} />
        </div>
      )}

      {showForm && (
        <div className="new-match-card">
          <label>Nom du programme<input type="text" placeholder="ex. Reprise post-entorse cheville" value={form.name} onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))} /></label>
          <label>Catégorie de blessure
            <select value={form.injuryCategory} onChange={(e) => setForm((f) => ({ ...f, injuryCategory: e.target.value }))}>
              {INJURY_CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
            </select>
          </label>
          <label>Notes générales<textarea rows={2} value={form.notes} onChange={(e) => setForm((f) => ({ ...f, notes: e.target.value }))} /></label>

          <div className="roster-form-section-title">Phases du programme</div>
          {form.phases.map((ph, i) => (
            <div key={ph.id} className="new-match-card" style={{ marginTop: 0, marginBottom: 10 }}>
              <label>Nom de la phase<input type="text" placeholder="ex. Phase 1 — Décharge et mobilité" value={ph.name} onChange={(e) => updatePhase(i, "name", e.target.value)} /></label>
              <label>Durée (jours)<input type="number" min="1" value={ph.dureeJours} onChange={(e) => updatePhase(i, "dureeJours", Number(e.target.value))} /></label>
              <label>Objectifs<input type="text" value={ph.objectifs} onChange={(e) => updatePhase(i, "objectifs", e.target.value)} /></label>
              <label>Exercices<textarea rows={2} value={ph.exercices} onChange={(e) => updatePhase(i, "exercices", e.target.value)} /></label>
              <button className="btn btn-ghost btn-small" onClick={() => removePhase(i)}>Retirer cette phase</button>
            </div>
          ))}
          <button className="btn btn-ghost btn-small" onClick={addPhase}>+ Ajouter une phase</button>

          <div className="form-actions">
            <button className="btn btn-ghost" onClick={() => setShowForm(false)}>Annuler</button>
            <button className="btn btn-primary" onClick={save}>Enregistrer le programme</button>
          </div>
        </div>
      )}

      {!showForm && INJURY_CATEGORIES.map((cat) => grouped[cat].length > 0 && (
        <div key={cat} style={{ marginBottom: 20 }}>
          <div className="panel-heading">{cat}</div>
          <div className="roster-grid">
            {grouped[cat].map((p) => (
              <div className="roster-card" key={p.id}>
                <div className="roster-card-info">
                  <div className="roster-card-name">{p.name}</div>
                  <div className="roster-card-position">{p.phases.length} phase{p.phases.length > 1 ? "s" : ""} · {p.phases.reduce((s, ph) => s + (Number(ph.dureeJours) || 0), 0)} jours au total</div>
                </div>
                <div className="roster-card-actions">
                  <button className="btn btn-ghost btn-small" onClick={() => openEdit(p)}>Modifier</button>
                  <button className="icon-btn" onClick={() => remove(p.id)} aria-label="Supprimer"><X size={14} /></button>
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}
      {!showForm && programs.length === 0 && <div className="empty-state">Aucun programme créé pour l'instant.</div>}
    </div>
  );
}

const HEALTH_FIELDS = [
  { key: "allergies", label: "Allergies", type: "textarea" },
  { key: "traitements", label: "Traitements / médicaments en cours", type: "textarea" },
  { key: "antecedents", label: "Antécédents médicaux notables", type: "textarea" },
  { key: "groupeSanguin", label: "Groupe sanguin", type: "text" },
  { key: "contactUrgenceNom", label: "Contact d'urgence — nom", type: "text" },
  { key: "contactUrgenceTel", label: "Contact d'urgence — téléphone", type: "text" },
  { key: "medecinTraitant", label: "Médecin traitant", type: "text" },
  { key: "certificatMedicalDate", label: "Certificat médical — date de validité", type: "date" },
  { key: "dateAdhesion", label: "Date d'adhésion au club", type: "date" },
  { key: "autorisationImage", label: "Autorisation à l'image", type: "select" },
  { key: "autorisationSortieTerritoire", label: "Autorisation de sortie du territoire", type: "select" },
  { key: "restrictions", label: "Restrictions particulières", type: "textarea" },
  { key: "notes", label: "Notes libres", type: "textarea" },
];

function emptyHealthProfile() {
  const p = {};
  HEALTH_FIELDS.forEach((f) => { p[f.key] = ""; });
  return p;
}

function HealthProfilesScreen({ roster, healthProfiles, setHealthProfiles }) {
  const [selectedId, setSelectedId] = useState(null);
  const [draft, setDraft] = useState(emptyHealthProfile());

  function openPlayer(id) {
    setSelectedId(id);
    setDraft({ ...emptyHealthProfile(), ...(healthProfiles[id] || {}) });
  }
  function save() {
    setHealthProfiles((prev) => ({ ...prev, [selectedId]: draft }));
    alert("Fiche santé enregistrée.");
  }

  function filledCount(id) {
    const p = healthProfiles[id];
    if (!p) return 0;
    return HEALTH_FIELDS.filter((f) => (p[f.key] || "").trim() !== "").length;
  }

  const selected = roster.find((p) => p.id === selectedId);

  return (
    <div>
      <p className="radar-note">Allergies, traitements, contact d'urgence et autres informations de santé — à ne renseigner que si tu es habilité à recueillir ces données pour tes joueurs (autorisation des parents pour les mineurs).</p>

      {!selectedId && (
        <div className="roster-grid">
          {roster.length === 0 && <div className="empty-state">Aucun joueur dans Effectifs.</div>}
          {roster.map((p) => {
            const count = filledCount(p.id);
            return (
              <div className="roster-card" key={p.id} onClick={() => openPlayer(p.id)} style={{ cursor: "pointer" }}>
                <div className="roster-card-info">
                  <div className="roster-card-name">{playerFullName(p)}</div>
                  <div className="roster-card-position">{count > 0 ? `${count}/${HEALTH_FIELDS.length} champs renseignés` : "Fiche vide"}</div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {selectedId && selected && (
        <div>
          <button className="btn btn-ghost btn-small" onClick={() => setSelectedId(null)} style={{ marginBottom: 16 }}>‹ Tous les joueurs</button>
          <div className="panel-heading">{playerFullName(selected)}</div>
          <div className="new-match-card">
            {HEALTH_FIELDS.map((f) => (
              <label key={f.key}>
                {f.label}
                {f.type === "textarea" ? (
                  <textarea rows={2} value={draft[f.key] || ""} onChange={(e) => setDraft((d) => ({ ...d, [f.key]: e.target.value }))} />
                ) : f.type === "select" ? (
                  <select value={draft[f.key] || ""} onChange={(e) => setDraft((d) => ({ ...d, [f.key]: e.target.value }))}>
                    <option value="">Non renseigné</option>
                    <option value="Oui">Oui</option>
                    <option value="Non">Non</option>
                  </select>
                ) : (
                  <input type={f.type} value={draft[f.key] || ""} onChange={(e) => setDraft((d) => ({ ...d, [f.key]: e.target.value }))} />
                )}
              </label>
            ))}
            <div className="form-actions">
              <button className="btn btn-primary" onClick={save}>Enregistrer</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function RosterComparisonScreen({ roster, allFullMatches }) {
  const [compareIds, setCompareIds] = useState([]);

  const enriched = useMemo(() => roster.map((p) => {
    const tags = gatherRosterPlayerTags(p.id, allFullMatches);
    const radarValues = computeRadarValues(tags, RADAR_AXES);
    return { ...p, radarValues, totalActions: tags.length };
  }), [roster, allFullMatches]);

  function toggleCompare(id) {
    setCompareIds((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : prev.length >= 4 ? prev : [...prev, id]));
  }

  const compareChartData = useMemo(() => RADAR_AXES.map((axis, i) => {
    const row = { axis: axis.label };
    compareIds.forEach((id) => {
      const p = enriched.find((x) => x.id === id);
      if (p) row[id] = p.radarValues[i].value;
    });
    return row;
  }), [compareIds, enriched]);

  return (
    <div>
      <p className="radar-note">Sélectionne 2 à 4 joueurs de ton effectif à comparer côte à côte, sur l'ensemble des matchs Studio tagués.</p>
      <div className="scouting-list">
        {enriched.length === 0 && <div className="empty-state">Aucun joueur dans Effectifs.</div>}
        {enriched.map((p) => (
          <label className="scout-obs-row" key={p.id} style={{ cursor: "pointer" }}>
            <span>
              <input type="checkbox" checked={compareIds.includes(p.id)} onChange={() => toggleCompare(p.id)} style={{ marginRight: 8 }} />
              {playerFullName(p)} <span className="scouting-club">{p.positionPrecise || p.position}</span>
            </span>
            <span className="scouting-meta">{p.totalActions} action{p.totalActions !== 1 ? "s" : ""}</span>
          </label>
        ))}
      </div>

      {compareIds.length >= 2 && (
        <>
          <div className="chart-wrap" style={{ marginTop: 20 }}>
            <ResponsiveContainer width="100%" height={340}>
              <RadarChart data={compareChartData} outerRadius="70%">
                <PolarGrid stroke="#26362C" />
                <PolarAngleAxis dataKey="axis" tick={{ fill: "#8FA599", fontSize: 11 }} />
                <PolarRadiusAxis domain={[0, 100]} tick={{ fill: "#8FA599", fontSize: 9 }} />
                <Tooltip contentStyle={{ background: "#182A21", border: "1px solid #26362C", borderRadius: 6, color: "#EEF3EC" }} />
                <Legend wrapperStyle={{ fontSize: 11 }} formatter={(id) => { const p = enriched.find((x) => x.id === id); return p ? playerFullName(p) : id; }} />
                {compareIds.map((id, i) => (
                  <Radar key={id} name={id} dataKey={id} stroke={COMPARE_COLORS[i]} fill={COMPARE_COLORS[i]} fillOpacity={0.18} />
                ))}
              </RadarChart>
            </ResponsiveContainer>
          </div>
          <div className="table-scroll">
            <table className="stat-table">
              <thead>
                <tr>
                  <th>Joueur</th>
                  {compareIds.map((id) => { const p = enriched.find((x) => x.id === id); return <th key={id}>{p ? playerFullName(p) : ""}</th>; })}
                </tr>
              </thead>
              <tbody>
                <tr><td>Poste</td>{compareIds.map((id) => { const p = enriched.find((x) => x.id === id); return <td key={id}>{p.positionPrecise || p.position}</td>; })}</tr>
                {RADAR_AXES.map((axis, i) => (
                  <tr key={axis.key}>
                    <td>{axis.label}</td>
                    {compareIds.map((id) => { const p = enriched.find((x) => x.id === id); return <td key={id}>{p.radarValues[i].hasData ? `${p.radarValues[i].value}%` : "—"}</td>; })}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </>
      )}
    </div>
  );
}

function PresenceHistoryScreen({ roster, allFullMatches }) {
  const [sessions, setSessions] = useState([]);
  const [selectedId, setSelectedId] = useState(null);

  useEffect(() => {
    try { setSessions(JSON.parse(localStorage.getItem("tf_sessions") || "[]")); } catch (e) { setSessions([]); }
  }, []);

  const studioMatches = allFullMatches.filter((m) => m.source !== "observation");

  function summaryFor(playerId) {
    let matchesInvolved = 0, starts = 0, subs = 0, totalMinutes = 0, minutesKnown = 0;
    studioMatches.forEach((m) => {
      const num = m.playerAssignments && Object.keys(m.playerAssignments).find((n) => m.playerAssignments[n] === playerId);
      if (!num) return;
      matchesInvolved++;
      const pm = m.playerMinutes && m.playerMinutes[playerId];
      if (pm) {
        if (pm.starter) starts++; else subs++;
        if (pm.minutes !== "" && pm.minutes != null) { totalMinutes += Number(pm.minutes) || 0; minutesKnown++; }
      }
    });
    const sessionsAttended = sessions.filter((s) => s.presence && s.presence[playerId]).length;
    return { matchesInvolved, starts, subs, totalMinutes, minutesKnown, sessionsAttended, sessionsTotal: sessions.length };
  }

  const selected = roster.find((p) => p.id === selectedId);

  return (
    <div>
      <p className="radar-note">Présence aux séances (déjà cochée dans Séance), et titulaire/remplaçant/minutes jouées renseignés dans Studio → Composition, pour chaque match.</p>

      {!selectedId && (
        <div className="roster-grid">
          {roster.length === 0 && <div className="empty-state">Aucun joueur dans Effectifs.</div>}
          {roster.map((p) => {
            const s = summaryFor(p.id);
            return (
              <div className="roster-card" key={p.id} onClick={() => setSelectedId(p.id)} style={{ cursor: "pointer" }}>
                <div className="roster-card-info">
                  <div className="roster-card-name">{playerFullName(p)}</div>
                  <div className="roster-card-position">{s.starts} titularisation{s.starts !== 1 ? "s" : ""} · {s.subs} entrée{s.subs !== 1 ? "s" : ""} en jeu</div>
                  <div className="roster-card-usage">{s.totalMinutes} min jouées{s.matchesInvolved > s.minutesKnown ? ` (${s.matchesInvolved - s.minutesKnown} match(s) sans minutes renseignées)` : ""} · {s.sessionsAttended}/{s.sessionsTotal} séances</div>
                </div>
              </div>
            );
          })}
        </div>
      )}

      {selectedId && selected && (
        <div>
          <button className="btn btn-ghost btn-small" onClick={() => setSelectedId(null)} style={{ marginBottom: 16 }}>‹ Tous les joueurs</button>
          <div className="panel-heading">{playerFullName(selected)}</div>

          <div className="panel-heading" style={{ marginTop: 16, fontSize: 13 }}>Matchs</div>
          <div className="table-scroll">
            <table className="stat-table">
              <thead><tr><th>Match</th><th>Date</th><th>Statut</th><th>Minutes</th></tr></thead>
              <tbody>
                {studioMatches.filter((m) => m.playerAssignments && Object.values(m.playerAssignments).includes(selected.id)).map((m) => {
                  const pm = m.playerMinutes && m.playerMinutes[selected.id];
                  return (
                    <tr key={m.id}>
                      <td>{m.name}</td>
                      <td>{formatDateFr(m.date)}</td>
                      <td>{pm ? (pm.starter ? "Titulaire" : "Remplaçant") : "Non renseigné"}</td>
                      <td>{pm && pm.minutes !== "" ? `${pm.minutes} min` : "—"}</td>
                    </tr>
                  );
                })}
                {studioMatches.filter((m) => m.playerAssignments && Object.values(m.playerAssignments).includes(selected.id)).length === 0 && (
                  <tr><td colSpan={4} className="empty-state">Aucun match avec ce joueur associé.</td></tr>
                )}
              </tbody>
            </table>
          </div>

          <div className="panel-heading" style={{ marginTop: 20, fontSize: 13 }}>Séances</div>
          <div className="table-scroll">
            <table className="stat-table">
              <thead><tr><th>Séance</th><th>Date</th><th>Présence</th></tr></thead>
              <tbody>
                {sessions.map((s) => (
                  <tr key={s.id}>
                    <td>{s.name}</td>
                    <td>{formatDateFr(s.date)}</td>
                    <td>{s.presence && s.presence[selected.id] ? "Présent" : "Absent"}</td>
                  </tr>
                ))}
                {sessions.length === 0 && <tr><td colSpan={3} className="empty-state">Aucune séance enregistrée.</td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

function DisciplineScreen({ roster, allFullMatches, records, setRecords }) {
  const yellowByPlayer = useMemo(() => gatherRosterCardDates(allFullMatches, "carton_jaune"), [allFullMatches]);
  const redByPlayer = useMemo(() => gatherRosterCardDates(allFullMatches, "carton_rouge"), [allFullMatches]);

  const playersWithCards = roster
    .map((p) => {
      const yellows = yellowByPlayer[p.id] || [];
      const reds = redByPlayer[p.id] || [];
      return { player: p, yellows, reds, triggers: detectYellowCardSuspensions(yellows) };
    })
    .filter((x) => x.yellows.length > 0 || x.reds.length > 0);

  function recordKey(playerId, tag) {
    return `${playerId}::${tag}`;
  }
  function updateRecord(key, field, value) {
    setRecords((prev) => ({ ...prev, [key]: { ...(prev[key] || {}), [field]: value } }));
  }

  function SanctionFields({ recKey }) {
    const rec = records[recKey] || {};
    return (
      <div className="roster-physical-grid">
        <label>Matchs de suspension<input type="number" min="0" value={rec.matches || ""} onChange={(e) => updateRecord(recKey, "matches", e.target.value)} /></label>
        <label>Jours de suspension<input type="number" min="0" value={rec.days || ""} onChange={(e) => updateRecord(recKey, "days", e.target.value)} /></label>
      </div>
    );
  }

  return (
    <div>
      <p className="radar-note">Cartons jaunes et rouges tagués dans Studio pour ton équipe. Règle appliquée : 3 cartons jaunes tombant dans les 3 mois suivant le premier déclenchent une suspension, effective 15 jours après le 3e carton. Renseigne le nombre de matchs/jours une fois la sanction connue de ta ligue.</p>

      {playersWithCards.length === 0 && <div className="empty-state">Aucun carton tagué pour l'instant.</div>}

      {playersWithCards.map(({ player, yellows, reds, triggers }) => (
        <div key={player.id} style={{ marginBottom: 24 }}>
          <div className="panel-heading">{playerFullName(player)}</div>
          <p className="scouting-meta" style={{ marginBottom: 10 }}>{yellows.length} carton{yellows.length > 1 ? "s" : ""} jaune{yellows.length > 1 ? "s" : ""} · {reds.length} carton{reds.length > 1 ? "s" : ""} rouge{reds.length > 1 ? "s" : ""} cette saison</p>

          {reds.map((d, i) => {
            const key = recordKey(player.id, `rouge-${d}-${i}`);
            return (
              <div className="scouting-card" key={key}>
                <div className="scouting-grade grade-f" style={{ fontSize: 11 }}>Rouge</div>
                <div className="scouting-info">
                  <div className="scouting-name">Carton rouge — {formatDateFr(d)}</div>
                  <SanctionFields recKey={key} />
                </div>
              </div>
            );
          })}

          {triggers.map((t, i) => {
            const key = recordKey(player.id, `3jaunes-${t.thirdCardDate}-${i}`);
            return (
              <div className="scouting-card" key={key}>
                <div className="scouting-grade grade-f" style={{ fontSize: 10 }}>3 J.</div>
                <div className="scouting-info">
                  <div className="scouting-name">Suspension déclenchée (3 cartons en 3 mois)</div>
                  <div className="scouting-meta">Cartons : {t.cardDates.map((d) => formatDateFr(d)).join(", ")} · Suspension effective à partir du {formatDateFr(t.suspensionStart)}</div>
                  <SanctionFields recKey={key} />
                </div>
              </div>
            );
          })}

          {triggers.length === 0 && reds.length === 0 && (
            <p className="hint" style={{ marginTop: 0 }}>{yellows.length}/3 cartons jaunes dans la fenêtre en cours — pas de suspension déclenchée pour l'instant.</p>
          )}
        </div>
      ))}
    </div>
  );
}

function MedicalScreen({ roster }) {
  const [subTab, setSubTab] = useState("overview");
  const [wellness, setWellness] = useState([]);
  const [rpeLog, setRpeLog] = useState([]);
  const [injuries, setInjuries] = useState([]);
  const [programs, setPrograms] = useState([]);
  const [healthProfiles, setHealthProfiles] = useState({});
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try { setWellness(JSON.parse(localStorage.getItem("tf_medical_wellness") || "[]")); } catch (e) { setWellness([]); }
    try { setRpeLog(JSON.parse(localStorage.getItem("tf_medical_rpe") || "[]")); } catch (e) { setRpeLog([]); }
    try { setInjuries(JSON.parse(localStorage.getItem("tf_medical_injuries") || "[]")); } catch (e) { setInjuries([]); }
    try { setPrograms(JSON.parse(localStorage.getItem("tf_medical_programs") || "[]")); } catch (e) { setPrograms([]); }
    try { setHealthProfiles(JSON.parse(localStorage.getItem("tf_medical_health_profiles") || "{}")); } catch (e) { setHealthProfiles({}); }
    setLoaded(true);
  }, []);

  function persist(key, setter) {
    return (updater) => {
      setter((prev) => {
        const next = typeof updater === "function" ? updater(prev) : updater;
        try { localStorage.setItem(key, JSON.stringify(next)); } catch (e) { alert("La sauvegarde a échoué."); }
        return next;
      });
    };
  }
  const setWellnessP = persist("tf_medical_wellness", setWellness);
  const setRpeLogP = persist("tf_medical_rpe", setRpeLog);
  const setInjuriesP = persist("tf_medical_injuries", setInjuries);
  const setProgramsP = persist("tf_medical_programs", setPrograms);
  const setHealthProfilesP = persist("tf_medical_health_profiles", setHealthProfiles);

  if (!loaded) return <div className="stats-screen"><div className="empty-state">Chargement…</div></div>;

  return (
    <div className="stats-screen">
      <div className="stats-screen-header">
        <div className="eyebrow">Assistant coaching</div>
        <h1>Suivi médical</h1>
        <p className="subtitle">Indice de Hooper, ressenti, anomalies physiques, blessures et programmes de réathlétisation.</p>
      </div>

      <div className="tabs">
        <button className={`tab ${subTab === "overview" ? "active" : ""}`} onClick={() => setSubTab("overview")}>Vue d'ensemble</button>
        <button className={`tab ${subTab === "injuries" ? "active" : ""}`} onClick={() => setSubTab("injuries")}>Blessures</button>
        <button className={`tab ${subTab === "programs" ? "active" : ""}`} onClick={() => setSubTab("programs")}>Programmes</button>
        <button className={`tab ${subTab === "health" ? "active" : ""}`} onClick={() => setSubTab("health")}>Fiche santé</button>
      </div>

      {subTab === "overview" && (
        <WellnessOverviewScreen roster={roster} wellness={wellness} setWellness={setWellnessP} rpeLog={rpeLog} setRpeLog={setRpeLogP} injuries={injuries} />
      )}
      {subTab === "injuries" && (
        <InjuriesScreen roster={roster} injuries={injuries} setInjuries={setInjuriesP} programs={programs} />
      )}
      {subTab === "programs" && (
        <ProgramsScreen programs={programs} setPrograms={setProgramsP} />
      )}
      {subTab === "health" && (
        <HealthProfilesScreen roster={roster} healthProfiles={healthProfiles} setHealthProfiles={setHealthProfilesP} />
      )}
    </div>
  );
}

